// (local patch 2026-10-02 IRIS) Refresh-token health.
//
// Incident 2026-10-02: four OAuth accounts' refresh tokens were rejected
// (invalid_grant) one by one over three days. Each was quietly marked 'error'
// and dropped from rotation, nothing told the operator, the log lines carried
// no time, and the client finally saw "all accounts are at their quota" --
// a quota diagnosis for what was really a re-login problem.
//
// This module is the observation + alert layer for that failure. It never
// sees or writes a token value: it records account names, times, the refresh
// token's expiry when upstream discloses one, and a short classified reason.
//
//   - stampConsole()      prefix every log line with local time (headless runs)
//   - noteRefreshResponseKeys()  log the token endpoint's FIELD NAMES once
//   - classifyRefreshError()     expired / invalid / rejected / server / network
//   - AuthHealth          per-account state, snapshot file, event log, alerts
//
// Files (siblings of the config, e.g. ~/.config/):
//   teamclaude.auth-health.json   latest snapshot, read by the dashboard/hooks
//   teamclaude.auth-events.jsonl  append-only history (rotated at 1 MB)
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';

const HOUR = 3_600_000;
const DAY = 24 * HOUR;

// ---------------------------------------------------------------- timestamps

function pad(n) { return String(n).padStart(2, '0'); }
export function stamp(d = new Date()) {
  return `${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

let stamped = false;
/**
 * Prefix console output with local time. Only when stdout is not a terminal
 * (the managed/headless server writes to log files); the interactive TUI keeps
 * its own layout. TEAMCLAUDE_LOG_TIME=1 forces it on, =0 off.
 */
export function stampConsole() {
  const flag = process.env.TEAMCLAUDE_LOG_TIME;
  if (stamped || flag === '0') return;
  if (process.stdout.isTTY && flag !== '1') return;
  stamped = true;
  for (const level of ['log', 'warn', 'error']) {
    const orig = console[level].bind(console);
    console[level] = (first, ...rest) => (typeof first === 'string'
      ? orig(`[${stamp()}] ${first}`, ...rest)
      : orig(first, ...rest));
  }
}

// ------------------------------------------------------------ classification

let sink = null;      // the running AuthHealth, if any
let keysNoted = false;

/** Log the token endpoint's response FIELD NAMES (never values), once per process. */
export function noteRefreshResponseKeys(data) {
  if (keysNoted || !data || typeof data !== 'object') return;
  keysNoted = true;
  const fields = Object.keys(data).sort();
  console.log(`[TeamClaude] Token refresh response fields: ${fields.join(', ')}`);
  sink?.event({ type: 'refresh-fields', fields });
}

/** Map a refresh failure to a small closed set of kinds. */
export function classifyRefreshError(err) {
  // (local patch 2026-11-25 IRIS) soft failures: not the login server's verdict (see account-manager authSoftState)
  if (err?.soft === true) return 'unconfirmed';
  if (err?.unexpectedReply === true) return 'unexpected-reply';
  const msg = String(err?.message || '');
  const st = err?.status;
  if (st === 400 || st === 401 || st === 403) {
    if (/expired/i.test(msg)) return 'expired';
    if (/not found|invalid/i.test(msg)) return 'invalid';
    return 'rejected';
  }
  if (typeof st === 'number' && st >= 500) return 'server';
  if (typeof st === 'number') return `http-${st}`;
  return 'network';
}

/** Short, token-free reason: the error code/description from the body, or a scrubbed message. */
export function safeReason(err) {
  const msg = String(err?.message || '');
  const m = msg.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      const j = JSON.parse(m[0]);
      const e = j.error;
      const code = typeof e === 'string' ? e : (e?.type || e?.code);
      const desc = j.error_description || e?.message;
      const out = [code, desc].filter(Boolean).join(': ');
      if (out) return out.slice(0, 160);
    } catch { /* fall through */ }
  }
  return msg.replace(/[A-Za-z0-9_\-.]{24,}/g, '[...]').slice(0, 160);
}

const KIND_KO = {
  expired: '로그인 열쇠 만료',
  invalid: '로그인 열쇠 무효 — 다른 곳에서 같은 계정 로그인 또는 갱신 중 끊김 가능',
  rejected: '인증 거절',
  unconfirmed: '로그인 확인이 여러 번 실패',
  'unexpected-reply': '로그인 서버가 아닌 곳의 답이 여러 번 옴',
};
// (local patch 2026-11-25 IRIS) only a refresh token the login server itself rejected can have been cut by a login elsewhere
const KIND_ELSEWHERE = new Set(['expired', 'invalid', 'rejected']);

// ------------------------------------------------------------------- notify

function psQuote(s) { return `'${String(s).replace(/'/g, "''")}'`; }

/** Windows balloon via a hidden PowerShell. Fire-and-forget; never throws. */
export function windowsNotify(title, body) {
  if (process.platform !== 'win32' || process.env.TEAMCLAUDE_NOTIFY === '0') return false;
  const script = [
    'Add-Type -AssemblyName System.Windows.Forms',
    'Add-Type -AssemblyName System.Drawing',
    '$n = New-Object System.Windows.Forms.NotifyIcon',
    '$n.Icon = [System.Drawing.SystemIcons]::Warning',
    "$n.BalloonTipIcon = 'Warning'",
    `$n.BalloonTipTitle = ${psQuote(String(title).slice(0, 60))}`,
    `$n.BalloonTipText = ${psQuote(String(body).slice(0, 250))}`,
    '$n.Visible = $true',
    '$n.ShowBalloonTip(15000)',
    'Start-Sleep -Seconds 20',
    '$n.Dispose()',
  ].join('\n');
  try {
    const encoded = Buffer.from(script, 'utf16le').toString('base64');
    const child = spawn('powershell.exe',
      ['-NoProfile', '-NonInteractive', '-WindowStyle', 'Hidden', '-EncodedCommand', encoded],
      { detached: true, stdio: 'ignore', windowsHide: true });
    child.on('error', () => {});
    child.unref();
    return true;
  } catch {
    return false;
  }
}

// ------------------------------------------------------------------- health

function siblingPath(configPath, suffix) {
  return configPath.endsWith('.json')
    ? configPath.replace(/\.json$/, suffix)
    : configPath + suffix;
}

function readJson(file) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; }
}

function keyOf(a) { return `${a.provider || 'anthropic'}:${a.name}`; }

export class AuthHealth {
  /**
   * @param accountManager  anything with an `accounts` array (name, provider,
   *   type, status, disabled, refreshToken, _deadRefreshToken, refreshTokenExpiresAt)
   * @param opts.configPath  teamclaude.json path; the two files sit beside it
   */
  constructor(accountManager, { configPath, notify = windowsNotify, now = () => Date.now(), warnDays = 3, remindMs = 6 * HOUR, intervalMs = 60_000 } = {}) {
    this.am = accountManager;
    this.file = siblingPath(configPath, '.auth-health.json');
    this.eventsFile = siblingPath(configPath, '.auth-events.jsonl');
    this.notify = notify;
    this.now = now;
    this.warnMs = warnDays * DAY;
    this.remindMs = remindMs;
    this.intervalMs = intervalMs;
    this.timer = null;
    // Carry history across restarts (last good refresh, last failure, when we
    // last alerted) so a restart neither forgets evidence nor re-alerts at once.
    this.records = new Map();
    const prev = readJson(this.file);
    for (const r of prev?.accounts || []) {
      if (r && r.name) this.records.set(`${r.provider || 'anthropic'}:${r.name}`, { ...r });
    }
  }

  rec(a) {
    const k = keyOf(a);
    let r = this.records.get(k);
    if (!r) {
      r = { name: a.name, provider: a.provider || 'anthropic', state: null, since: null, lastOkAt: null, lastFail: null, notifiedAt: null, expiryNotifiedAt: null };
      this.records.set(k, r);
    }
    return r;
  }

  stateOf(a) {
    if (a.type !== 'oauth') return 'n/a';
    if (a.disabled) return 'disabled';
    // (local patch 2026-11-25 IRIS) a login under recheck: 'checking' first, 'needs-login' after repeated failures
    const soft = this.am.authSoftState?.(a);
    if (soft) return soft;
    if (a.status === 'error' || (a._deadRefreshToken && a._deadRefreshToken === a.refreshToken)) return 'needs-login';
    const exp = Number(a.refreshTokenExpiresAt) || null;
    if (exp && exp - this.now() <= this.warnMs) return 'expiring';
    return 'ok';
  }

  /** (local patch 2026-11-25 IRIS) the account manager confirmed a doubted login without a new login. */
  noteSelfRecovery(account) { this.rec(account).selfRecovered = true; }

  /** Called by ensureTokenFresh after a successful refresh. */
  refreshOk(account) {
    const r = this.rec(account);
    r.lastOkAt = new Date(this.now()).toISOString();
    if (account.refreshTokenExpiresAt) r.refreshTokenExpiresAt = new Date(Number(account.refreshTokenExpiresAt)).toISOString();
    this.event({ type: 'refresh-ok', account: account.name, provider: r.provider, refreshTokenExpiresAt: r.refreshTokenExpiresAt || null });
    this.check();
  }

  /** Called by ensureTokenFresh after a failed refresh (any kind). */
  refreshFailed(account, err) {
    const r = this.rec(account);
    const kind = classifyRefreshError(err);
    const prevFail = r.lastFail;
    // A rejection right after a network failure on the same account is the
    // "rotation lost in transit" signature: upstream may have rotated the
    // token while the reply never arrived.
    const afterNetwork = kind !== 'network' && kind !== 'server' && prevFail?.kind === 'network'
      && this.now() - Date.parse(prevFail.at) < DAY;
    r.lastFail = { at: new Date(this.now()).toISOString(), kind, status: err?.status ?? null, reason: safeReason(err), ...(afterNetwork && { afterNetwork: true }) };
    this.event({ type: 'refresh-failed', account: account.name, provider: r.provider, ...r.lastFail });
    this.check();
  }

  /** Per-account view for the status API. */
  describe(a) {
    const r = this.records.get(keyOf(a));
    const exp = Number(a.refreshTokenExpiresAt) || (r?.refreshTokenExpiresAt ? Date.parse(r.refreshTokenExpiresAt) : null);
    return {
      state: this.stateOf(a),
      // (local patch 2026-11-25 IRIS) while rechecking: how many checks failed, when the next one runs
      check: this.am.authSoftView?.(a) || null,
      since: r?.since || null,
      lastOkAt: r?.lastOkAt || null,
      lastFail: r?.lastFail || null,
      refreshTokenExpiresAt: exp ? new Date(exp).toISOString() : null,
      daysLeft: exp ? Math.floor((exp - this.now()) / DAY) : null,
    };
  }

  /** Recompute every account's state, alert on transitions, write the snapshot. */
  check() {
    const now = this.now();
    const newlyDown = [];
    const backUp = []; // (local patch 2026-11-25 IRIS) told "needs re-login" earlier, working again now
    const expiring = [];
    for (const a of this.am.accounts || []) {
      if (a.type !== 'oauth') continue;
      const r = this.rec(a);
      const state = this.stateOf(a);
      if (a.refreshTokenExpiresAt) r.refreshTokenExpiresAt = new Date(Number(a.refreshTokenExpiresAt)).toISOString();
      if (state !== r.state) {
        if (r.state !== null || state === 'needs-login') {
          this.event({ type: 'state', account: a.name, provider: r.provider, from: r.state, to: state });
        }
        if (state === 'needs-login') {
          console.error(`[TeamClaude] AUTH: account "${a.name}" needs re-login (${r.lastFail?.kind || 'rejected'}) — rotation is now one account smaller`);
        } else if (r.state === 'needs-login') {
          console.log(`[TeamClaude] AUTH: account "${a.name}" is back (${state})`);
          // only when the account came back BY ITSELF (confirmAuthRecovered) - after a re-login the user already knows
          if (r.selfRecovered && r.notifiedAt && (state === 'ok' || state === 'expiring')) backUp.push(r);
          r.notifiedAt = null;
        }
        r.state = state;
        r.since = new Date(now).toISOString();
        if (state !== 'needs-login' && state !== 'checking') delete r.selfRecovered;
      }
      if (state === 'needs-login' && (!r.notifiedAt || now - Date.parse(r.notifiedAt) >= this.remindMs)) {
        newlyDown.push(r);
      }
      if (state === 'expiring' && (!r.expiryNotifiedAt || now - Date.parse(r.expiryNotifiedAt) >= DAY)) {
        expiring.push({ r, a });
      }
    }
    if (newlyDown.length) {
      const names = newlyDown.map(r => r.name.split('@')[0]).join(', ');
      const kinds = [...new Set(newlyDown.map(r => KIND_KO[r.lastFail?.kind] || KIND_KO.rejected))].join(' / ');
      // (local patch 2026-11-25 IRIS) the "do not log in elsewhere" sentence only for refusals the login server gave
      const elsewhere = newlyDown.some(r => KIND_ELSEWHERE.has(r.lastFail?.kind || 'rejected'));
      const sent = this.notify('IRIS 중계기: 재로그인 필요',
        `${names} 계정이 순환에서 빠졌습니다(${kinds}). 대시보드에서 「다시 확인」을 눌러 보고, 그래도 안 되면 같은 계정에 다시 로그인하세요.`
        + (elsewhere ? ' 중계기 계정을 데스크톱 앱이나 다른 PC에서 로그인하면 중계기의 열쇠가 끊길 수 있습니다.' : ''));
      for (const r of newlyDown) r.notifiedAt = new Date(now).toISOString();
      this.event({ type: 'alert', alert: 'needs-login', accounts: newlyDown.map(r => r.name), shown: !!sent });
    }
    if (backUp.length) {
      const sent = this.notify('IRIS 중계기: 다시 정상',
        `${backUp.map(r => r.name.split('@')[0]).join(', ')} 계정이 순환에 돌아왔습니다. 다시 로그인할 필요가 없습니다.`);
      this.event({ type: 'alert', alert: 'recovered', accounts: backUp.map(r => r.name), shown: !!sent });
    }
    if (expiring.length) {
      const parts = expiring.map(({ a }) => {
        const exp = Number(a.refreshTokenExpiresAt);
        const d = new Date(exp);
        return `${a.name.split('@')[0]} ${Math.max(0, Math.floor((exp - now) / DAY))}일 뒤(${d.getMonth() + 1}/${d.getDate()})`;
      }).join(', ');
      const sent = this.notify('IRIS 중계기: 로그인 만료 임박',
        `${parts} 로그인이 만료됩니다. 미리 대시보드의 계정 추가 단추로 같은 계정에 다시 로그인하세요.`);
      for (const { r } of expiring) r.expiryNotifiedAt = new Date(now).toISOString();
      this.event({ type: 'alert', alert: 'expiring', accounts: expiring.map(({ a }) => a.name), shown: !!sent });
    }
    this.write();
  }

  snapshot() {
    const accounts = [...this.records.values()].filter(r =>
      (this.am.accounts || []).some(a => a.type === 'oauth' && keyOf(a) === `${r.provider}:${r.name}`));
    const count = s => accounts.filter(r => r.state === s).length;
    return {
      updatedAt: new Date(this.now()).toISOString(),
      pid: process.pid,
      summary: { needsLogin: count('needs-login'), checking: count('checking'), expiring: count('expiring'), ok: count('ok') },
      accounts,
    };
  }

  write() {
    try {
      const tmp = `${this.file}.${process.pid}.tmp`;
      fs.writeFileSync(tmp, JSON.stringify(this.snapshot(), null, 2));
      fs.renameSync(tmp, this.file);
    } catch (err) {
      console.error(`[TeamClaude] AUTH: could not write health file: ${err.message}`);
    }
  }

  event(obj) {
    try {
      try {
        if (fs.statSync(this.eventsFile).size > 1_000_000) fs.renameSync(this.eventsFile, `${this.eventsFile}.1`);
      } catch { /* no file yet */ }
      fs.appendFileSync(this.eventsFile, JSON.stringify({ t: new Date(this.now()).toISOString(), ...obj }) + '\n');
    } catch { /* history is best-effort */ }
  }

  start() {
    sink = this;
    this.event({ type: 'start', pid: process.pid });
    setTimeout(() => this.check(), 5_000).unref?.();
    this.timer = setInterval(() => this.check(), this.intervalMs);
    this.timer.unref?.();
    return this;
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    if (sink === this) sink = null;
  }
}

/** Wire-up used by serverCommand. */
export function startAuthHealth(accountManager, opts) {
  stampConsole();
  return new AuthHealth(accountManager, opts).start();
}

// (local patch 2026-10-02 IRIS) tests for src/auth-health.js and the exhausted-message split.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { AuthHealth, classifyRefreshError, safeReason, stamp } from './src/auth-health.js';
import { exhaustedMessage } from './src/server.js';

const DAY = 86_400_000;

function tmpConfig() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'tc-auth-'));
  return { dir, configPath: path.join(dir, 'teamclaude.json') };
}
function acct(name, extra = {}) {
  return { name, provider: 'anthropic', type: 'oauth', status: 'active', disabled: false, refreshToken: 'rt-' + name, ...extra };
}
function rejected(body) {
  const e = new Error(`Token refresh failed (400): ${body}`);
  e.status = 400;
  return e;
}

test('classifyRefreshError separates expired / invalid / server / network', () => {
  assert.equal(classifyRefreshError(rejected('{"error":"invalid_grant","error_description":"Refresh token expired"}')), 'expired');
  assert.equal(classifyRefreshError(rejected('{"error":"invalid_grant","error_description":"Refresh token not found or invalid"}')), 'invalid');
  assert.equal(classifyRefreshError(Object.assign(new Error('x'), { status: 403 })), 'rejected');
  assert.equal(classifyRefreshError(Object.assign(new Error('x'), { status: 502 })), 'server');
  assert.equal(classifyRefreshError(new TypeError('fetch failed')), 'network');
});

test('safeReason keeps the error code/description and never echoes long token-like strings', () => {
  assert.equal(safeReason(rejected('{"error":"invalid_grant","error_description":"Refresh token expired"}')), 'invalid_grant: Refresh token expired');
  const leaked = safeReason(new Error('bad sk-ant-ort01-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA thing'));
  assert.ok(!leaked.includes('AAAAAAAAAAAAAAAAAAAAAAAA'), leaked);
});

test('stamp formats MM-DD HH:MM:SS', () => {
  assert.equal(stamp(new Date(2026, 9, 2, 7, 5, 9)), '10-02 07:05:09');
});

test('a rejected refresh -> needs-login, one alert, health file + event log written, no token in files', () => {
  const { configPath } = tmpConfig();
  const a = acct('user3@example.test');
  const b = acct('user0@example.test');
  const am = { accounts: [a, b] };
  const alerts = [];
  let now = Date.UTC(2026, 9, 2, 7, 0, 0);
  const h = new AuthHealth(am, { configPath, notify: (t, body) => { alerts.push([t, body]); return true; }, now: () => now });
  h.check();
  assert.equal(alerts.length, 0);

  // what ensureTokenFresh does on an auth rejection, then reports
  a.status = 'error';
  a._deadRefreshToken = a.refreshToken;
  h.refreshFailed(a, rejected('{"error":"invalid_grant","error_description":"Refresh token not found or invalid"}'));
  assert.equal(alerts.length, 1);
  assert.match(alerts[0][1], /user3/);
  assert.match(alerts[0][1], /다시 로그인/);

  const snap = JSON.parse(fs.readFileSync(configPath.replace(/\.json$/, '.auth-health.json'), 'utf8'));
  assert.equal(snap.summary.needsLogin, 1);
  assert.equal(snap.summary.ok, 1);
  const rec = snap.accounts.find(r => r.name === 'user3@example.test');
  assert.equal(rec.state, 'needs-login');
  assert.equal(rec.lastFail.kind, 'invalid');

  const events = fs.readFileSync(configPath.replace(/\.json$/, '.auth-events.jsonl'), 'utf8');
  assert.match(events, /refresh-failed/);
  assert.match(events, /"alert":"needs-login"/);
  for (const text of [JSON.stringify(snap), events]) assert.ok(!text.includes('rt-user'), 'token value leaked');

  // still down: no repeat inside the reminder window, one reminder after it
  now += 60_000; h.check();
  assert.equal(alerts.length, 1);
  now += 6 * 3_600_000; h.check();
  assert.equal(alerts.length, 2);

  // re-login: new refresh token, status back to active -> recovered, no alert
  a.refreshToken = 'rt-new'; a.status = 'active';
  now += 60_000; h.check();
  assert.equal(alerts.length, 2);
  assert.equal(h.describe(a).state, 'ok');
  assert.match(fs.readFileSync(configPath.replace(/\.json$/, '.auth-events.jsonl'), 'utf8'), /"from":"needs-login","to":"ok"/);
});

test('a restart does not re-alert an account that was already alerted', () => {
  const { configPath } = tmpConfig();
  const now = Date.UTC(2026, 9, 2, 7, 0, 0);
  const a = acct('user1@example.test', { status: 'error' });
  const alerts = [];
  new AuthHealth({ accounts: [a] }, { configPath, notify: () => { alerts.push(1); return true; }, now: () => now }).check();
  assert.equal(alerts.length, 1);
  new AuthHealth({ accounts: [a] }, { configPath, notify: () => { alerts.push(1); return true; }, now: () => now + 60_000 }).check();
  assert.equal(alerts.length, 1);
});

test('refresh-token expiry inside 3 days -> expiring alert once a day; describe gives daysLeft', () => {
  const { configPath } = tmpConfig();
  let now = Date.UTC(2026, 9, 2, 7, 0, 0);
  const a = acct('user2@example.test', { refreshTokenExpiresAt: now + 10 * DAY });
  const alerts = [];
  const h = new AuthHealth({ accounts: [a] }, { configPath, notify: (t) => { alerts.push(t); return true; }, now: () => now });
  h.check();
  assert.equal(alerts.length, 0);
  assert.equal(h.describe(a).daysLeft, 10);
  now += 8 * DAY; h.check();
  assert.equal(alerts.length, 1);
  assert.match(alerts[0], /만료 임박/);
  now += 3_600_000; h.check();
  assert.equal(alerts.length, 1);
  now += DAY; h.check();
  assert.equal(alerts.length, 2);
});

test('a rejection right after a network failure is flagged afterNetwork', () => {
  const { configPath } = tmpConfig();
  const now = Date.UTC(2026, 9, 2, 7, 0, 0);
  const a = acct('user2@example.test');
  const h = new AuthHealth({ accounts: [a] }, { configPath, notify: () => true, now: () => now });
  h.refreshFailed(a, new TypeError('fetch failed'));
  a.status = 'error';
  h.refreshFailed(a, rejected('{"error":"invalid_grant","error_description":"Refresh token expired"}'));
  assert.equal(h.describe(a).lastFail.afterNetwork, true);
});

test('exhaustedMessage names re-login accounts instead of calling them quota', () => {
  const am = { accounts: [
    { name: 'max@x', status: 'active' },
    { name: 'user0@example.test', status: 'error' },
    { name: 'user1@example.test', status: 'active', refreshToken: 'r1', _deadRefreshToken: 'r1' },
    { name: 'off@x', status: 'active', disabled: true },
  ] };
  const m = exhaustedMessage(am, 'claude-opus-5-5', 120);
  assert.match(m, /1 at their quota or rate limit/);
  assert.match(m, /2 need re-login/);
  assert.match(m, /user0@example.test, user1@example.test/);
  assert.match(m, /Quota resets in 120s/);
  assert.match(m, /1 more disabled/);

  const plain = exhaustedMessage({ accounts: [{ name: 'a', status: 'active' }] }, null, 0);
  assert.equal(plain, 'No account can serve this request: all 1 account are at their quota or rate limit. Retry shortly.');
});

// 429 black box (local patch 2026-10-03 IRIS).
//
// Why: a subscription (OAuth) token refuses an Opus/Sonnet request that does
// not look like Claude Code with a 429 that carries NO unified quota headers —
// on every account alike. The proxy read that as a per-minute throttle, paused
// the account, hopped to an idle sibling (which refused it too), then waited
// 60s per retry. One such client kept two accounts paused for hours, and the
// idle account it always landed on looked broken (2026-10-02: 46/46 refused on
// a healthy account). Upstream discards the 429 body and the request log skips
// a pure 429-then-retry, so nothing said which program sent it.
//
// This module records every upstream 429 as one JSON line next to the config
// (`teamclaude.reject-events.jsonl`, rotated at 1 MB): account, model, the
// quota-header verdict, Anthropic's own error text, and who sent it — the
// client's user-agent / x-app / beta header, whether the system prompt carries
// the Claude Code identity, and (Windows) the owning process of the client's
// socket. Never the message content and never a token.

import fs from 'node:fs';
import { spawn, execFile } from 'node:child_process';
import { getConfigPath } from './config.js';

const MAX_FILE = 1_000_000;
// Process details (one PowerShell) are fetched once per PID; the PID itself
// comes from netstat (~0.1 s) while the client's socket is still open — a
// PowerShell-only lookup took ~1.8 s and missed clients that hang up at once.
const DETAIL_CACHE_MAX = 200;
// Markers a Claude Code / Agent SDK system prompt starts with. Searched in the
// raw body bytes, so no JSON parse of a multi-megabyte context is needed.
const CC_MARKERS = [
  "You are Claude Code, Anthropic's official CLI for Claude",
  "You are a Claude agent, built on Anthropic's Claude Agent SDK",
];

let fileOverride = null;
let seq = 0;
const detailByPid = new Map();

/** Tests point the log elsewhere; null restores the default. */
export function setRejectLogFile(file) { fileOverride = file; }

export function rejectLogFile() {
  if (fileOverride) return fileOverride;
  const cfg = getConfigPath();
  return cfg.endsWith('.json') ? cfg.replace(/\.json$/, '.reject-events.jsonl') : `${cfg}.reject-events.jsonl`;
}

function clip(v, n) {
  if (v == null) return null;
  // Control characters out (log-line safety), then cap.
  const s = String(v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
  return s.length > n ? `${s.slice(0, n)}…` : s;
}

/** True when any unified (subscription quota) header came back. */
export function hasUnifiedHeaders(rl) {
  return Object.keys(rl || {}).some(k => k.startsWith('anthropic-ratelimit-unified'));
}

/** The quota-status headers only (values are short words like allowed/rejected). */
export function unifiedStatuses(rl) {
  const out = {};
  for (const [k, v] of Object.entries(rl || {})) {
    if (k.startsWith('anthropic-ratelimit-unified') && k.endsWith('status')) {
      out[k.slice('anthropic-ratelimit-unified-'.length) || 'status'] = clip(v, 40);
    }
  }
  return out;
}

/** Which identity, if any, the request's system prompt opens with. */
export function identityOf(body) {
  if (!body || !body.length) return null;
  const buf = Buffer.isBuffer(body) ? body : Buffer.from(String(body));
  for (const m of CC_MARKERS) {
    // The marker may sit inside a JSON string, where ' stays as-is.
    if (buf.indexOf(m) !== -1) return m.startsWith('You are Claude Code') ? 'claude-code' : 'agent-sdk';
  }
  return 'none';
}

/** Short summary of who sent the request — headers only, no content. */
export function describeClient(req, body) {
  const h = req?.headers || {};
  return {
    ua: clip(h['user-agent'], 120),
    app: clip(h['x-app'], 40),
    beta: clip(h['anthropic-beta'], 200),
    identity: identityOf(body),
    bodyBytes: body?.length ?? 0,
    port: req?.socket?.remotePort ?? null,
    proxyPort: req?.socket?.localPort ?? null,
  };
}

/**
 * The PID owning the client end of a proxy connection, from `netstat -ano`
 * text: the row whose LOCAL port is the client's port and whose FOREIGN port
 * is the proxy's. TIME_WAIT rows carry PID 0 and are skipped.
 */
export function parseNetstatPid(text, clientPort, proxyPort) {
  for (const line of String(text || '').split(/\r?\n/)) {
    const m = line.trim().split(/\s+/);
    if (m.length < 5 || m[0] !== 'TCP') continue;
    const local = m[1].slice(m[1].lastIndexOf(':') + 1);
    const foreign = m[2].slice(m[2].lastIndexOf(':') + 1);
    const pid = Number(m[m.length - 1]);
    if (local === String(clientPort) && (!proxyPort || foreign === String(proxyPort)) && pid > 0) return pid;
  }
  return null;
}

/** Anthropic's own error text out of a 429 body (JSON or plain). */
export function upstreamError(text) {
  if (!text) return null;
  try {
    const j = JSON.parse(text);
    const e = j?.error || j;
    return { type: clip(e?.type, 60), message: clip(e?.message ?? text, 300) };
  } catch {
    return { type: null, message: clip(text, 300) };
  }
}

/** Read at most `cap` bytes of a fetch Response body as text; never throws. */
export async function readCapped(res, cap = 8192) {
  try {
    const reader = res.body?.getReader?.();
    if (!reader) return '';
    const parts = [];
    let n = 0;
    while (n < cap) {
      const { done, value } = await reader.read();
      if (done) break;
      parts.push(Buffer.from(value));
      n += value.length;
    }
    try { await reader.cancel(); } catch { /* already closed */ }
    return Buffer.concat(parts).subarray(0, cap).toString('utf8');
  } catch {
    try { await res.body?.cancel(); } catch { /* ignore */ }
    return '';
  }
}

function append(obj) {
  const file = rejectLogFile();
  try {
    try {
      if (fs.statSync(file).size > MAX_FILE) fs.renameSync(file, `${file}.1`);
    } catch { /* no file yet */ }
    fs.appendFileSync(file, JSON.stringify({ t: new Date().toISOString(), ...obj }) + '\n');
  } catch { /* the black box is best-effort, never breaks a request */ }
}

/**
 * Record one upstream 429. Returns the event id so a later decision line can
 * point back at it. `lookupPid` (default: Windows only) adds a follow-up
 * {type:'client'} line naming the process that owns the client's socket.
 */
export function noteReject(fields, { lookupPid = process.platform === 'win32' && process.env.TEAMCLAUDE_REJECT_PID !== '0' } = {}) {
  const id = `${process.pid}-${++seq}`;
  append({ type: '429', id, ...fields });
  const port = fields?.client?.port;
  if (lookupPid && port) clientProcess(port, fields?.client?.proxyPort, id);
  return id;
}

/** Record the proxy's decision about a 429 (e.g. request-specific passthrough). */
export function noteDecision(fields) { append({ type: 'decision', ...fields }); }

function clientProcess(port, proxyPort, ref) {
  // Step 1 — PID from netstat while the client's socket is still open (the
  // proxy has not answered yet when the first 429 is noted).
  execFile('netstat', ['-ano', '-p', 'TCP'], { windowsHide: true, timeout: 5000, maxBuffer: 8 * 1024 * 1024 }, (err, stdout) => {
    const pid = err ? null : parseNetstatPid(stdout, port, proxyPort);
    if (!pid) { append({ type: 'client', ref, port, found: false }); return; }
    // Cached for 10 minutes only: Windows reuses PIDs.
    const hit = detailByPid.get(pid);
    if (hit && Date.now() - hit.at < 600_000) { append({ type: 'client', ref, port, ...hit.info, cached: true }); return; }
    // Step 2 — who that PID is (still answers after the socket closes, as long
    // as the process lives). One hidden PowerShell per new PID.
    const script = [
      '$ErrorActionPreference = "SilentlyContinue"',
      `$p = Get-CimInstance Win32_Process -Filter "ProcessId=${Number(pid)}"`,
      'if (-not $p) { "{}"; exit }',
      '$q = Get-CimInstance Win32_Process -Filter "ProcessId=$($p.ParentProcessId)"',
      '@{ name = $p.Name; cmd = $p.CommandLine; parentPid = $p.ParentProcessId; parentName = $q.Name; parentCmd = $q.CommandLine } | ConvertTo-Json -Compress',
    ].join('\n');
    try {
      const child = spawn('powershell.exe',
        ['-NoProfile', '-NonInteractive', '-WindowStyle', 'Hidden', '-EncodedCommand', Buffer.from(script, 'utf16le').toString('base64')],
        { stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true });
      let out = '';
      child.stdout.on('data', d => { out += d; });
      child.on('error', () => append({ type: 'client', ref, port, pid, detail: false }));
      child.on('close', () => {
        let j = {};
        try { j = JSON.parse(out.trim() || '{}'); } catch { /* ignore */ }
        if (!j.name) { append({ type: 'client', ref, port, pid, exited: true }); return; }
        const info = {
          pid, name: clip(j.name, 60), cmd: clip(j.cmd, 300),
          parentPid: j.parentPid ?? null, parentName: clip(j.parentName, 60), parentCmd: clip(j.parentCmd, 200),
        };
        detailByPid.set(pid, { info, at: Date.now() });
        if (detailByPid.size > DETAIL_CACHE_MAX) detailByPid.delete(detailByPid.keys().next().value);
        append({ type: 'client', ref, port, ...info });
      });
    } catch { append({ type: 'client', ref, port, pid, detail: false }); }
  });
}

// 429 black box + request-specific passthrough (local patch 2026-10-03 IRIS).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  setRejectLogFile, identityOf, describeClient, upstreamError, hasUnifiedHeaders, unifiedStatuses, noteReject, parseNetstatPid,
} from './src/reject-log.js';
import { AccountManager } from './src/account-manager.js';
import { createProxyRequestListener } from './src/server.js';

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'tc-reject-'));
const logFile = path.join(tmp, 'reject.jsonl');
setRejectLogFile(logFile);
const readLog = () => (fs.existsSync(logFile) ? fs.readFileSync(logFile, 'utf8').trim().split('\n').filter(Boolean).map(l => JSON.parse(l)) : []);
const resetLog = () => { try { fs.unlinkSync(logFile); } catch { /* none */ } };

const CC = "You are Claude Code, Anthropic's official CLI for Claude.";
const body = (system) => Buffer.from(JSON.stringify({
  model: 'claude-opus-5-5', max_tokens: 1,
  ...(system ? { system: [{ type: 'text', text: system }] } : {}),
  messages: [{ role: 'user', content: 'secret user words' }],
}));

test('helpers: identity, client summary, error text, quota headers', () => {
  assert.equal(identityOf(body(CC)), 'claude-code');
  assert.equal(identityOf(body("You are a Claude agent, built on Anthropic's Claude Agent SDK.")), 'agent-sdk');
  assert.equal(identityOf(body('You are a helpful bot')), 'none');
  assert.equal(identityOf(Buffer.alloc(0)), null);
  const c = describeClient({ headers: { 'user-agent': 'claude-cli/9 (external, cli)\n', 'x-app': 'cli' }, socket: { remotePort: 5555 } }, body(null));
  assert.equal(c.ua, 'claude-cli/9 (external, cli)');
  assert.equal(c.identity, 'none');
  assert.equal(c.port, 5555);
  assert.ok(!JSON.stringify(c).includes('secret user words'), 'no message content');
  assert.deepEqual(upstreamError('{"type":"error","error":{"type":"rate_limit_error","message":"Nope"}}'), { type: 'rate_limit_error', message: 'Nope' });
  assert.equal(upstreamError('plain text').message, 'plain text');
  assert.equal(upstreamError(''), null);
  assert.equal(hasUnifiedHeaders({ 'anthropic-ratelimit-unified-5h-status': 'allowed' }), true);
  assert.equal(hasUnifiedHeaders({}), false);
  assert.deepEqual(unifiedStatuses({ 'anthropic-ratelimit-unified-5h-status': 'allowed', 'anthropic-ratelimit-unified-5h-utilization': '0.1' }), { '5h-status': 'allowed' });
});

test('parseNetstatPid picks the client row (local = client port, foreign = proxy port), skips TIME_WAIT', () => {
  const text = [
    '  Proto  Local Address          Foreign Address        State           PID',
    '  TCP    127.0.0.1:3456         0.0.0.0:0              LISTENING       28428',
    '  TCP    127.0.0.1:3456         127.0.0.1:52245        ESTABLISHED     28428',
    '  TCP    127.0.0.1:52245        127.0.0.1:3456         ESTABLISHED     9001',
    '  TCP    127.0.0.1:50150        127.0.0.1:3456         TIME_WAIT       0',
  ].join('\r\n');
  assert.equal(parseNetstatPid(text, 52245, 3456), 9001);
  assert.equal(parseNetstatPid(text, 50150, 3456), null);
  assert.equal(parseNetstatPid(text, 1, 3456), null);
  assert.equal(parseNetstatPid('', 1, 2), null);
});

test('noteReject writes one line, no pid lookup when disabled, rotates past 1 MB', () => {
  resetLog();
  noteReject({ account: 'a', client: { port: 1 } }, { lookupPid: false });
  const lines = readLog();
  assert.equal(lines.length, 1);
  assert.equal(lines[0].type, '429');
  assert.equal(lines[0].account, 'a');
  fs.writeFileSync(logFile, 'x'.repeat(1_000_001));
  noteReject({ account: 'b' }, { lookupPid: false });
  assert.ok(fs.existsSync(`${logFile}.1`));
  assert.equal(readLog().length, 1);
  resetLog();
});

// ---- integration: fake upstream + real proxy listener ----

function fakeUpstream(handler) {
  return new Promise(resolve => {
    const hits = [];
    const srv = http.createServer((req, res) => {
      const chunks = [];
      req.on('data', c => chunks.push(c));
      req.on('end', () => { const b = Buffer.concat(chunks); hits.push({ auth: req.headers.authorization, body: b.toString() }); handler(req, res, b); });
    });
    srv.listen(0, '127.0.0.1', () => resolve({ srv, hits, url: `http://127.0.0.1:${srv.address().port}` }));
  });
}

function proxyFor(upstreamUrl, { apiKey = false } = {}) {
  const far = Date.now() + 24 * 3600 * 1000;
  const am = new AccountManager(apiKey ? [
    { name: 'key-a', type: 'apikey', apiKey: 'tok-ka' },
    { name: 'key-b', type: 'apikey', apiKey: 'tok-kb' },
  ] : [
    { name: 'acct-a', type: 'oauth', accessToken: 'tok-a', refreshToken: 'r-a', expiresAt: far },
    { name: 'acct-b', type: 'oauth', accessToken: 'tok-b', refreshToken: 'r-b', expiresAt: far },
  ], 1);
  const listener = createProxyRequestListener({ accountManager: am, upstream: upstreamUrl, config: {} });
  return new Promise(resolve => {
    const srv = http.createServer(listener);
    srv.listen(0, '127.0.0.1', () => resolve({ srv, am, url: `http://127.0.0.1:${srv.address().port}` }));
  });
}

function send(url, b) {
  return new Promise((resolve, reject) => {
    const t0 = Date.now();
    const req = http.request(`${url}/v1/messages`, { method: 'POST', headers: { 'content-type': 'application/json', 'anthropic-version': '2023-06-01', 'user-agent': 'test-client/1' } }, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, text: Buffer.concat(chunks).toString(), ms: Date.now() - t0 }));
    });
    req.on('error', reject);
    req.end(b);
  });
}

const REFUSE = JSON.stringify({ type: 'error', error: { type: 'rate_limit_error', message: 'Refused: not Claude Code' } });

// Claude Code's session-start quota check, as sent (no system prompt).
const QUOTA_CHECK = Buffer.from(JSON.stringify({ model: 'claude-opus-5-5', max_tokens: 1, messages: [{ role: 'user', content: 'quota' }], metadata: { user_id: 'x' } }));

test('no-identity request refused without quota headers → passed through on the FIRST account (no hop: the idle sibling is never touched)', async () => {
  resetLog();
  const up = await fakeUpstream((req, res) => { res.writeHead(429, { 'content-type': 'application/json', 'request-id': 'req_q' }); res.end(REFUSE); });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, QUOTA_CHECK);
    assert.equal(r.status, 429);
    assert.equal(r.headers['request-id'], 'req_q');
    assert.ok(r.ms < 5_000, `answered in ${r.ms} ms`);
    assert.equal(up.hits.length, 1, 'one upstream call only');
    assert.equal(px.am.isPaused(0), false);
    assert.equal(px.am.isPaused(1), false);
    const log = readLog();
    assert.equal(log.find(e => e.type === 'decision')?.decision, 'request-specific:no-identity');
  } finally { px.srv.close(); up.srv.close(); }
});

test('API-key accounts keep the original 429 path (no passthrough decision)', async () => {
  resetLog();
  const up = await fakeUpstream((req, res) => { res.writeHead(429, { 'content-type': 'application/json', 'retry-after': '1' }); res.end(REFUSE); });
  const px = await proxyFor(up.url, { apiKey: true });
  try {
    const r = await send(px.url, QUOTA_CHECK);
    assert.equal(r.status, 429);
    assert.ok(up.hits.length >= 2, 'retried as before');
    assert.equal(readLog().filter(e => e.type === 'decision').length, 0);
  } finally { px.srv.close(); up.srv.close(); }
});

test('request WITH identity refused on two accounts without quota headers → Anthropic 429 passed through at once, nobody stays paused', async () => {
  resetLog();
  const up = await fakeUpstream((req, res) => {
    res.writeHead(429, { 'content-type': 'application/json', 'request-id': 'req_x' }); res.end(REFUSE);
  });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, body(CC));
    assert.equal(r.status, 429);
    assert.ok(r.text.includes('Refused: not Claude Code'), 'client sees the real reason');
    assert.equal(r.headers['request-id'], 'req_x');
    assert.ok(r.ms < 10_000, `answered in ${r.ms} ms, no 60 s wait`);
    assert.equal(up.hits.length, 2, 'tried exactly two accounts');
    assert.notEqual(up.hits[0].auth, up.hits[1].auth);
    assert.equal(px.am.isPaused(0), false);
    assert.equal(px.am.isPaused(1), false);
    const log = readLog();
    assert.equal(log.filter(e => e.type === '429').length, 2);
    const d = log.find(e => e.type === 'decision');
    assert.equal(d?.decision, 'request-specific');
    assert.equal(log[0].client.identity, 'claude-code');
    assert.equal(log[0].client.ua, 'test-client/1');
    assert.equal(log[0].error.message, 'Refused: not Claude Code');
    assert.ok(!fs.readFileSync(logFile, 'utf8').includes('secret user words'));
    assert.ok(!fs.readFileSync(logFile, 'utf8').includes('tok-'));
  } finally { px.srv.close(); up.srv.close(); }
});

test('429 WITH quota headers keeps the old path (pause + retry, no passthrough decision)', async () => {
  resetLog();
  let n = 0;
  const up = await fakeUpstream((req, res) => {
    n++;
    if (n <= 2) {
      res.writeHead(429, { 'content-type': 'application/json', 'retry-after': '1', 'anthropic-ratelimit-unified-5h-status': 'allowed' });
      res.end(REFUSE); return;
    }
    res.writeHead(200, { 'content-type': 'application/json' }); res.end('{"type":"message"}');
  });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, body(CC));
    assert.equal(r.status, 200, 'retried and served');
    const log = readLog();
    assert.equal(log.filter(e => e.type === '429').length, 2);
    assert.equal(log.filter(e => e.type === 'decision').length, 0);
    assert.equal(log.find(e => e.type === '429').noQuotaHeaders, false); // (2026-11-25: not log[0] - a cached client line may come first)
  } finally { px.srv.close(); up.srv.close(); }
});

test('Windows: a client that hangs up at once is still named (PID caught while the socket is open)', { skip: process.platform !== 'win32' }, async () => {
  resetLog();
  const saved = process.env.TEAMCLAUDE_REJECT_PID;
  process.env.TEAMCLAUDE_REJECT_PID = '1';
  const up = await fakeUpstream((req, res) => { res.writeHead(429, { 'content-type': 'application/json' }); res.end(REFUSE); });
  const px = await proxyFor(up.url);
  try {
    const r = await send(px.url, body(null)); // http.request without keep-alive: closes right after
    assert.equal(r.status, 429);
    let clients = [];
    for (let i = 0; i < 40 && !clients.some(c => c.name); i++) {
      await new Promise(res => setTimeout(res, 250));
      clients = readLog().filter(e => e.type === 'client');
    }
    const named = clients.find(c => c.name);
    assert.ok(named, `client named: ${JSON.stringify(clients)}`);
    assert.equal(named.pid, process.pid, 'the test process itself sent it');
    assert.match(named.name, /node/i);
  } finally {
    if (saved === undefined) delete process.env.TEAMCLAUDE_REJECT_PID; else process.env.TEAMCLAUDE_REJECT_PID = saved;
    px.srv.close(); up.srv.close();
  }
});

// (local patch 2026-10-10 IRIS) tests for the Codex paid-credit fallback.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { AccountManager } from './src/account-manager.js';
import { normalizeCodexUsage, normalizeCodexCredits } from './src/codex-quota.js';
import { Prober } from './src/prober.js';

const WEEK = 604800;

function usagePayload({ pct = 100, limitReached = false, hasCredits = true, balance = '62500.0', overage = false, spend = false, unlimited = false } = {}) {
  return {
    plan_type: 'pro',
    rate_limit: { allowed: true, limit_reached: limitReached,
      primary_window: { used_percent: pct, limit_window_seconds: WEEK, reset_after_seconds: 1000, reset_at: Math.floor(Date.now() / 1000) + 1000 },
      secondary_window: null },
    credits: { has_credits: hasCredits, unlimited, overage_limit_reached: overage, balance, approx_local_messages: [15625, 81250] },
    spend_control: { reached: spend, individual_limit: null },
  };
}

function codex(name) {
  return { name, provider: 'codex', type: 'oauth', accessToken: 'at-' + name, accountId: 'id-' + name };
}

function fleet({ creditFallback = { codex: true }, weeklyResetFirst = true } = {}) {
  const am = new AccountManager([codex('codex-1'), codex('codex-2'), codex('codex-3')], 1,
    { weeklyResetFirst, creditFallback });
  return am;
}

function feed(am, index, opts) {
  am.applyUsageData(index, normalizeCodexUsage(usagePayload(opts)), { observedAt: Date.now() });
}

const quiet = (fn) => { const log = console.log; console.log = () => {}; try { return fn(); } finally { console.log = log; } };

test('normalizeCodexCredits reads the credits block and treats a missing block as unknown', () => {
  const c = normalizeCodexCredits(usagePayload({ balance: '52200.8639650000', limitReached: true }));
  assert.equal(c.hasCredits, true);
  assert.equal(c.balance, 52200.863965);
  assert.equal(c.limitReached, true);
  assert.equal(c.overageLimitReached, false);
  assert.deepEqual(c.approxLocalMessages, [15625, 81250]);
  assert.equal(normalizeCodexCredits({ rate_limit: {} }), null);
  assert.equal(normalizeCodexUsage(usagePayload()).credits.balance, 62500);
});

test('off by default: a spent fleet with credits still gets no account', () => {
  const am = fleet({ creditFallback: null });
  for (const i of [0, 1, 2]) feed(am, i);
  assert.equal(am.getActiveAccount(null, 'gpt-6-astra', null, null, 'codex'), null);
  assert.equal(am.creditBlockReason(am.accounts[1]), 'off');
});

test('plan headroom always wins over credits', () => {
  const am = fleet();
  feed(am, 0); feed(am, 1);
  feed(am, 2, { pct: 7 });
  const a = quiet(() => am.getActiveAccount(null, 'gpt-6-astra', null, null, 'codex'));
  assert.equal(a.name, 'codex-3');
  assert.equal(am.creditMode.codex, null);
});

test('every plan spent: serve on credits, largest balance first, then stay put', () => {
  const am = fleet();
  feed(am, 0, { balance: '52200' });
  feed(am, 1, { balance: '62500' });
  feed(am, 2, { balance: '61000' });
  const a = quiet(() => am.getActiveAccount(null, 'gpt-6-astra', null, null, 'codex'));
  assert.equal(a.name, 'codex-2');
  assert.equal(am.creditMode.codex.account, 'codex-2');
  // A later read shows codex-3 richer; we stay on codex-2 (prompt cache).
  feed(am, 2, { balance: '99999' });
  const b = quiet(() => am.getActiveAccount(null, 'gpt-6-astra', null, null, 'codex'));
  assert.equal(b.name, 'codex-2');
  assert.equal(am.creditMode.codex.requests, 2);
});

