// (local patch 2026-11-10 IRIS) tests: one person's Claude login and Codex login share an
// email, and the email used to be both rows' default name. A Claude login made after a Codex
// one was then read as "the same account" and overwrote the Codex row ("Updated account").
// These tests pin that a Claude row and a Codex row are never one account, and that the
// existing matching (same Claude account again, Codex by name, quota restore) still works.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sameIdentity, distinctAccounts, findUpsertTarget, nextCodexName } from './src/identity.js';
import { AccountManager } from './src/account-manager.js';
import { mergeAccountsForSave } from './src/account-pairing.js';

const EMAIL = 'teacher@school.example';
const codexRow = (extra = {}) => ({ name: EMAIL, type: 'oauth', provider: 'codex', importFrom: 'C:/soul/_agent/codex/auth.json', ...extra });
const claudeIncoming = (extra = {}) => ({
  name: EMAIL, type: 'oauth', accountUuid: 'uuid-1', orgUuid: 'org-1', orgName: 'School',
  accessToken: 'claude-at', refreshToken: 'claude-rt', expiresAt: 1, ...extra,
});

test('Codex first, then Claude with the same email: the Claude login is added as a new row', () => {
  assert.equal(findUpsertTarget([codexRow()], claudeIncoming()), -1, 'email-named Codex row (old installs)');
  assert.equal(findUpsertTarget([codexRow({ name: 'codex-1', displayName: EMAIL })], claudeIncoming()), -1, 'codex-N row');
  assert.equal(findUpsertTarget([codexRow()], claudeIncoming({ accountUuid: undefined, orgUuid: undefined, orgName: undefined })), -1,
    'even a Claude record with no UUID yet does not fall back to the Codex row by name');
});

test('a Claude record and a Codex record are never the same identity and always distinct', () => {
  assert.equal(sameIdentity(codexRow(), claudeIncoming()), false);
  assert.equal(sameIdentity(claudeIncoming(), codexRow()), false);
  assert.equal(distinctAccounts(codexRow(), claudeIncoming()), true);
  assert.equal(distinctAccounts(claudeIncoming(), codexRow({ accountUuid: 'uuid-1', orgUuid: 'org-1' })), true,
    'a Codex row that picked up the Claude UUID from an earlier overwrite is still a different account');
});

test('baseline: the same Claude account logging in again still updates its own row', () => {
  const existing = claudeIncoming({ accessToken: 'old' });
  assert.equal(findUpsertTarget([codexRow(), existing], claudeIncoming()), 1);
  const legacy = { name: EMAIL, type: 'oauth', accessToken: 'old' }; // Claude row from before UUIDs were stored
  assert.equal(findUpsertTarget([legacy], claudeIncoming()), 0);
  assert.equal(sameIdentity({ name: EMAIL, provider: 'anthropic' }, { name: EMAIL }), true, "explicit 'anthropic' equals no provider");
});

test('baseline: Codex records still match each other by name', () => {
  assert.equal(sameIdentity({ name: 'codex-1', provider: 'codex' }, { name: 'codex-1', provider: 'codex' }), true);
  assert.equal(sameIdentity({ name: 'codex-1', provider: 'codex' }, { name: 'codex-2', provider: 'codex' }), false);
});

test('nextCodexName picks the smallest free codex-N', () => {
  assert.equal(nextCodexName([]), 'codex-1');
  assert.equal(nextCodexName(undefined), 'codex-1');
  assert.equal(nextCodexName([{ name: EMAIL }, { name: 'codex-1', provider: 'codex' }, { name: 'codex-3', provider: 'codex' }]), 'codex-2');
});

test('saving pairs each row with its own disk row when Claude and Codex share a name', () => {
  const claude = claudeIncoming();
  const codex = codexRow();
  const merged = mergeAccountsForSave([claude, codex], [], [claude, codex]);
  assert.equal(merged.length, 2);
  assert.equal(merged[0].accessToken, 'claude-at');
  assert.equal(merged[1].provider, 'codex');
  assert.equal(merged[1].accessToken, undefined, 'no Claude token copied onto the Codex row');
  assert.equal(merged[1].accountUuid, undefined, 'no Claude UUID copied onto the Codex row');
});

test('quota restore: a state row saved before this patch (no provider) still restores a Codex account', () => {
  const quiet = (fn) => { const log = console.log; console.log = () => {}; try { return fn(); } finally { console.log = log; } };
