test('project swap: top-level only, byte-exact elsewhere', () => {
  const B = s => Buffer.from(s, 'utf8');
  const out = rewriteGoogleProject(B('{"project":"old-1","request":{"project":"nested","n":123456789012345678901234567890}}'), 'new-2');
  assert.equal(out.toString(), '{"project":"new-2","request":{"project":"nested","n":123456789012345678901234567890}}');
  // a string value that merely contains the text is not a key
  const s = '{"note":"\\"project\\":\\"old\\"","project" : "old"}';
  assert.equal(rewriteGoogleProject(B(s), 'NEW').toString(), '{"note":"\\"project\\":\\"old\\"","project" : "NEW"}');
  // duplicate top-level keys: all replaced
  assert.equal(rewriteGoogleProject(B('{"project":"a","x":[1,{"project":"b"}],"project":"c"}'), 'P').toString(), '{"project":"P","x":[1,{"project":"b"}],"project":"P"}');
  // unchanged cases return the SAME buffer
  for (const raw of ['', 'not json', '[{"project":"a"}]', '{"project":1}', '{"project":"a"', '{"a":1}', '{"project":"same"}']) {
    const buf = B(raw);
    assert.equal(rewriteGoogleProject(buf, 'same'), buf, raw);
  }
  const zipped = B('{"project":"a"}');
  assert.equal(rewriteGoogleProject(zipped, 'b', 'gzip'), zipped);
  assert.equal(rewriteGoogleProject(B('{"project":"a"}'), 'bad"id').toString(), '{"project":"a"}');
  // unicode elsewhere survives
  assert.equal(rewriteGoogleProject(B('{"t":"한글 ✓","project":"x"}'), 'y').toString(), '{"t":"한글 ✓","project":"y"}');
  assert.deepEqual(topLevelProjectRanges(B('{"project":"ab"}')), [{ start: 12, end: 14 }]);
});

