test('real server: Google routed, swapped, fenced; 403 halts; 429 fails over only when spent', { timeout: 40000 }, async t => {
  const temp = await mkdtemp(join(tmpdir(), 'teamclaude-google-'));
  let child;
  const hits = { anthropic: [], google: [] };
  // per-test behaviour of the fake Google: by bearer token
  const googleMode = { G1: 'ok', G2: 'ok' };
  const quotaLeft = { G1: 0.5, G2: 0.5 };
  const anthropic = http.createServer((req, res) => {
    let b = ''; req.on('data', d => { b += d; });
    req.on('end', () => {
      hits.anthropic.push({ path: req.url, auth: req.headers.authorization || req.headers['x-api-key'] });
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ id: 'm', type: 'message', role: 'assistant', content: [{ type: 'text', text: 'ok' }], stop_reason: 'end_turn', usage: { input_tokens: 1, output_tokens: 1 } }));
    });
  });
  const google = http.createServer((req, res) => {
    let b = ''; req.on('data', d => { b += d; });
    req.on('end', () => {
      const tok = String(req.headers.authorization || '').replace(/^Bearer /, '');
      hits.google.push({ path: req.url, auth: tok, body: b });
      const json = (code, o) => { res.writeHead(code, { 'content-type': 'application/json' }); res.end(JSON.stringify(o)); };
      if (req.url.startsWith('/v1internal:loadCodeAssist')) return json(200, { cloudaicompanionProject: `proj-${tok}`, currentTier: { id: 'free-tier' } });
      if (req.url.startsWith('/v1internal:retrieveUserQuotaSummary')) return json(200, { groups: [{ displayName: 'Gemini Models', buckets: [{ id: 'gemini-weekly', window: 'weekly', remainingFraction: quotaLeft[tok], resetTime: new Date(Date.now() + 86400000).toISOString() }] }] });
      const mode = googleMode[tok];
      if (mode === 'tos') return json(403, { error: { code: 403, status: 'PERMISSION_DENIED', details: [{ reason: 'TOS_VIOLATION' }] } });
      if (mode === 'deny') return json(403, { error: { code: 403, message: 'Caller does not have permission' } });
      if (mode === '429') return json(429, { error: { code: 429, status: 'RESOURCE_EXHAUSTED' } });
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      res.end(`data: ${JSON.stringify({ response: { candidates: [{ content: { parts: [{ text: 'hi' }] } }], usageMetadata: { promptTokenCount: 3, candidatesTokenCount: 1 } } })}\n\n`);
    });
  });
  t.after(async () => {
    if (child && child.exitCode === null && child.signalCode === null) { const closed = once(child, 'exit'); child.kill(); await closed; }
    for (const s of [anthropic, google]) { s.closeAllConnections(); if (s.listening) await new Promise(r => s.close(r)); }
    if (!resolve(temp).startsWith(resolve(tmpdir(), 'teamclaude-google-'))) throw new Error('unsafe cleanup');
    await rm(temp, { recursive: true, force: true });
  });
  for (const s of [anthropic, google]) { s.listen(0, '127.0.0.1'); await once(s, 'listening'); }
  const aUrl = `http://127.0.0.1:${anthropic.address().port}`, gUrl = `http://127.0.0.1:${google.address().port}`;
  const res0 = http.createServer(); res0.listen(0, '127.0.0.1'); await once(res0, 'listening');
  const port = res0.address().port; await new Promise(r => res0.close(r));
  const base = `http://127.0.0.1:${port}`;
  const h1 = await googleHome(join(temp, 'g1'), 'G1'), h2 = await googleHome(join(temp, 'g2'), 'G2');
  const now = Date.now();
  const config = {
    proxy: { port, apiKey: 'test-proxy-key' }, upstream: aUrl, upstreamProxy: false, quotaProbeSeconds: 0, warmupSeconds: 0, autoUpdate: false, switchThreshold: 0.99,
    accounts: [
      { id: 'fx-a', name: 'claude-1', type: 'oauth', provider: 'anthropic', accessToken: 'A-TOKEN', refreshToken: 'RA', expiresAt: now + 86400000, upstream: aUrl },
      { id: 'fx-g1', name: 'google-1', type: 'oauth', provider: 'google', importFrom: h1, upstream: gUrl },
      { id: 'fx-g2', name: 'google-2', type: 'oauth', provider: 'google', importFrom: h2, upstream: gUrl },
    ],
  };
  const configPath = join(temp, 'teamclaude.json');
  await writeFile(configPath, JSON.stringify(config));
  const haltFile = join(temp, 'halt.json');
  child = spawn(process.execPath, ['src/index.js', 'server', '--headless'], {
    cwd: resolve('.'), env: { ...process.env, TEAMCLAUDE_CONFIG: configPath, IRIS_GATE_GOOGLE_HALT_FILE: haltFile, TEAMCLAUDE_HOST: '127.0.0.1' }, stdio: ['ignore', 'pipe', 'pipe'],
  });
  let log = ''; child.stdout.on('data', d => { log += d; }); child.stderr.on('data', d => { log += d; });
  for (let i = 0; i < 100; i++) { try { const r = await fetch(`${base}/teamclaude/status`); if (r.ok) break; } catch { /* not yet */ } await delay(100); }
  const status = async () => (await fetch(`${base}/teamclaude/status`)).json();
  const gen = (project = 'proj-PC-LOGIN') => fetch(`${base}/v1internal:streamGenerateContent?alt=sse`, {
    method: 'POST', headers: { authorization: 'Bearer PC-LOGIN', 'content-type': 'application/json', 'user-agent': 'antigravity/cli/1.5.14 (test)' },
    body: JSON.stringify({ project, model: 'gemini-3.8-flash-low', request: { contents: [{ role: 'user', parts: [{ text: 'hi' }] }], sessionId: '1' } }),
  });

  const st0 = await status();
  assert.equal(st0.google.supported, true);
  assert.deepEqual(st0.accounts.map(a => a.provider), ['anthropic', 'google', 'google']);

  // 1. a Google request goes to Google with a Google token and the account's project
  let r = await gen(); assert.equal(r.status, 200); assert.match(await r.text(), /hi/);
  const lastGen = hits.google.filter(h => h.path.startsWith('/v1internal:streamGenerateContent')).at(-1);
  assert.equal(lastGen.auth, 'G1');
  assert.equal(JSON.parse(lastGen.body).project, 'proj-G1');
  // 2. a Claude request goes to Anthropic with the Claude token
  r = await fetch(`${base}/v1/messages`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-claude-code-session-id': 's1' }, body: JSON.stringify({ model: 'claude-sonnet-4-6', max_tokens: 5, messages: [{ role: 'user', content: 'hi' }] }) });
  assert.equal(r.status, 200); await r.text();
  // fences: no Google token ever reached Anthropic, no Claude token or PC login ever reached Google
  assert.ok(hits.anthropic.length >= 1);
  assert.ok(hits.anthropic.every(h => h.auth === 'Bearer A-TOKEN'), JSON.stringify(hits.anthropic));
  assert.ok(hits.google.every(h => h.auth === 'G1' || h.auth === 'G2'), JSON.stringify(hits.google.map(h => h.auth)));

  // 3. an unexplained 429 is returned as is — no failover to google-2
  googleMode.G1 = '429';
  const before429 = hits.google.filter(h => h.auth === 'G2' && h.path.includes('Generate')).length;
  r = await gen(); assert.equal(r.status, 429); await r.text();
  assert.equal(hits.google.filter(h => h.auth === 'G2' && h.path.includes('Generate')).length, before429);
  // 4. a 429 with the quota confirmed spent fails over to google-2
  quotaLeft.G1 = 0;
  r = await gen(); assert.equal(r.status, 200); await r.text();
  assert.equal(hits.google.filter(h => h.path.includes('Generate')).at(-1).auth, 'G2');
  assert.equal(JSON.parse(hits.google.filter(h => h.path.includes('Generate')).at(-1).body).project, 'proj-G2');
  // 5. a plain 403 on the serving account is returned — no failover
  googleMode.G2 = 'deny';
  const g1Before = hits.google.filter(h => h.auth === 'G1' && h.path.includes('Generate')).length;
  r = await gen(); assert.equal(r.status, 403); await r.text();
  assert.equal(hits.google.filter(h => h.auth === 'G1' && h.path.includes('Generate')).length, g1Before);
  assert.equal((await status()).google.halt, null);
  // 6. a suspension signal halts every Google request; Claude keeps working
  googleMode.G2 = 'tos';
  r = await gen(); assert.equal(r.status, 403); await r.text();
  const st = await status();
  assert.equal(st.google.halt.account, 'google-2');
  assert.ok(existsSync(haltFile));
  const countAll = hits.google.length;
  googleMode.G1 = 'ok'; googleMode.G2 = 'ok'; quotaLeft.G1 = 0.5;
  r = await gen(); assert.equal(r.status, 403); assert.match(await r.text(), /stopped all Google accounts/);
  assert.equal(hits.google.length, countAll, 'nothing may be sent to Google while halted');
  r = await fetch(`${base}/v1/messages`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ model: 'claude-sonnet-4-6', max_tokens: 5, messages: [{ role: 'user', content: 'hi' }] }) });
  assert.equal(r.status, 200); await r.text();
  // 7. the operator clears it
  r = await fetch(`${base}/teamclaude/google/resume`, { method: 'POST' });
  assert.deepEqual(await r.json(), { ok: true, wasHalted: true });
  assert.equal(existsSync(haltFile), false);
  r = await gen(); assert.equal(r.status, 200, log.slice(-2000)); await r.text();
  // 8. a pin to the Claude account cannot serve a Google request
  r = await fetch(`${base}/tc-acct/claude-1/v1internal:streamGenerateContent?alt=sse`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{"project":"x"}' });
  assert.equal(r.status, 400); await r.text();
  // 9. a pin to a Google account works through the prefix (agy keeps CLOUD_CODE_URL's path)
  r = await fetch(`${base}/tc-acct/google-1/v1internal:loadCodeAssist`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{"metadata":{"ideType":"ANTIGRAVITY"}}' });
  assert.equal(r.status, 200); assert.equal((await r.json()).cloudaicompanionProject, 'proj-G1');
  assert.ok(hits.anthropic.every(h => h.auth === 'Bearer A-TOKEN'));
  assert.ok(hits.google.every(h => h.auth === 'G1' || h.auth === 'G2'));
});

