test('real server: background-read suspension halts; unknown project and compressed bodies are not sent', { timeout: 40000 }, async t => {
  const temp = await mkdtemp(join(tmpdir(), 'teamclaude-google-'));
  let child;
  const hits = [];
  const projectMode = { G3: 'fail', G4: 'tos' };
  const google = http.createServer((req, res) => {
    let b = ''; req.on('data', d => { b += d; });
    req.on('end', () => {
      const tok = String(req.headers.authorization || '').replace(/^Bearer /, '');
      hits.push({ path: req.url, auth: tok });
      const json = (code, o) => { res.writeHead(code, { 'content-type': 'application/json' }); res.end(JSON.stringify(o)); };
      if (req.url.startsWith('/v1internal:loadCodeAssist')) {
        if (projectMode[tok] === 'fail') return json(500, { error: { code: 500 } });
        if (projectMode[tok] === 'tos') return json(403, { error: { code: 403, details: [{ reason: 'TOS_VIOLATION' }] } });
        return json(200, { cloudaicompanionProject: `proj-${tok}` });
      }
      if (req.url.startsWith('/v1internal:retrieveUserQuotaSummary')) return json(200, { groups: [] });
      res.writeHead(200, { 'content-type': 'text/event-stream' }); res.end('data: {}\n\n');
    });
  });
  t.after(async () => {
    if (child && child.exitCode === null && child.signalCode === null) { const closed = once(child, 'exit'); child.kill(); await closed; }
    google.closeAllConnections(); if (google.listening) await new Promise(r => google.close(r));
    if (!resolve(temp).startsWith(resolve(tmpdir(), 'teamclaude-google-'))) throw new Error('unsafe cleanup');
    await rm(temp, { recursive: true, force: true });
  });
  google.listen(0, '127.0.0.1'); await once(google, 'listening');
  const gUrl = `http://127.0.0.1:${google.address().port}`;
  const res0 = http.createServer(); res0.listen(0, '127.0.0.1'); await once(res0, 'listening');
  const port = res0.address().port; await new Promise(r => res0.close(r));
  const base = `http://127.0.0.1:${port}`;
  const h3 = await googleHome(join(temp, 'g3'), 'G3'), h4 = await googleHome(join(temp, 'g4'), 'G4');
  const config = { proxy: { port }, upstream: gUrl, upstreamProxy: false, quotaProbeSeconds: 0, warmupSeconds: 0, autoUpdate: false,
    accounts: [{ id: 'g3', name: 'google-3', type: 'oauth', provider: 'google', importFrom: h3, upstream: gUrl }, { id: 'g4', name: 'google-4', type: 'oauth', provider: 'google', importFrom: h4, upstream: gUrl, disabled: true }] };
  const configPath = join(temp, 'teamclaude.json');
  await writeFile(configPath, JSON.stringify(config));
  const haltFile = join(temp, 'halt.json');
  child = spawn(process.execPath, ['src/index.js', 'server', '--headless'], { cwd: resolve('.'), env: { ...process.env, TEAMCLAUDE_CONFIG: configPath, IRIS_GATE_GOOGLE_HALT_FILE: haltFile }, stdio: ['ignore', 'pipe', 'pipe'] });
  let log = ''; child.stdout.on('data', d => { log += d; }); child.stderr.on('data', d => { log += d; });
  for (let i = 0; i < 100; i++) { try { const r = await fetch(`${base}/teamclaude/status`); if (r.ok) break; } catch { /* not yet */ } await delay(100); }
  const gen = (headers = {}) => fetch(`${base}/v1internal:streamGenerateContent?alt=sse`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: '{"project":"proj-PC","model":"gemini-3.8-flash-low"}' });
  const sentGen = () => hits.filter(h => h.path.includes('Generate')).length;
  // 1. the project cannot be learned -> not sent
  let r = await gen(); assert.equal(r.status, 503, log.slice(-1500)); assert.match(await r.text(), /could not learn the Google project/);
  assert.equal(sentGen(), 0);
  // 2. a compressed body -> not sent
  r = await gen({ 'content-encoding': 'gzip' }); assert.equal(r.status, 415); await r.text();
  assert.equal(sentGen(), 0);
  // 3. a request without a top-level project (loadCodeAssist) still goes
  r = await fetch(`${base}/v1internal:loadCodeAssist`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{"metadata":{}}' });
  assert.equal(r.status, 500); await r.text();
  // 4. only google-4 left, whose project read answers with a suspension signal -> halt, generation never sent
  config.accounts[0].disabled = true; config.accounts[1].disabled = false;
  await writeFile(configPath, JSON.stringify(config));
  await fetch(`${base}/teamclaude/reload`, { method: 'POST' }).then(x => x.text());
  r = await gen(); assert.equal(r.status, 403, log.slice(-1500)); assert.match(await r.text(), /stopped all Google accounts/);
  assert.equal(sentGen(), 0);
  assert.ok(existsSync(haltFile));
  assert.equal((await (await fetch(`${base}/teamclaude/status`)).json()).google.halt.account, 'google-4');
  const n = hits.length;
