  assert.equal(hits.length, n, 'nothing at all reaches Google while halted');
});

// local patch 2026-11-23 IRIS: Google Antigravity (agy) as the third subscription provider.
//
// The credential's OWNER is agy, not this proxy: every Google account has its own
// isolated home folder (e.g. ~/.config/iris-gate-google/g1) where agy itself logged
// in and keeps `.gemini/antigravity-cli/antigravity-oauth-token`. The proxy only
// READS that file. To get a fresh token it runs agy in that folder and reads the
// file again — it never mints Google tokens with agy's OAuth client itself, and it
// never writes Google tokens into the TeamClaude config.
//
// Everything else follows the provider.js rule: a passthrough. The only body edit
// is the top-level `"project"` value, which Google binds to the account
// (loadCodeAssist → cloudaicompanionProject), done as a byte-level string swap so
// the rest of the body is forwarded byte for byte.

import { readFileSync, statSync, mkdirSync } from 'node:fs';
import { spawn } from 'node:child_process';
import path from 'node:path';
import os from 'node:os';

export const GOOGLE_UPSTREAM = 'https://daily-cloudcode-pa.googleapis.com';
const DEFAULT_UA = 'antigravity/cli/1.5.14 (aidev_client; os_type=windows; arch=amd64; auth_method=consumer)';

// The User-Agent of the last real agy request that came through. The background
// reads (project, quota) present themselves the same way agy does, so they look
// like what they are: the same client asking the same zero-spend questions.
let lastClientUA = null;
export function noteGoogleClientUA(ua) {
  if (typeof ua === 'string' && /^antigravity\//.test(ua) && ua.length < 300) lastClientUA = ua;
}
export const googleUA = () => lastClientUA || DEFAULT_UA;

/** Where agy keeps the token inside an account's home folder. */
export function googleTokenPath(home) {
  return path.join(home, '.gemini', 'antigravity-cli', 'antigravity-oauth-token');
}

/**
 * Read an account's token file. Returns null when it is missing or unreadable.
 * Shape: { accessToken, refreshToken, expiresAt (ms), email, mtimeMs }.
 */
export function readGoogleToken(home) {
  if (!home) return null;
  const file = googleTokenPath(home);
  try {
    const st = statSync(file);
    const j = JSON.parse(readFileSync(file, 'utf8'));
    const t = j?.token || {};
    if (typeof t.access_token !== 'string' || !t.access_token) return null;
    const exp = Date.parse(t.expiry || '');
    return {
      accessToken: t.access_token,
      refreshToken: typeof t.refresh_token === 'string' ? t.refresh_token : null,
      expiresAt: Number.isFinite(exp) ? exp : null,
      email: typeof j.id_token_email === 'string' ? j.id_token_email : null,
      mtimeMs: st.mtimeMs,
    };
  } catch {
    return null;
  }
}

/** agy.exe of the official install, unless the config names another one. */
export function defaultAgyExe() {
  if (process.env.IRIS_AGY_EXE) return process.env.IRIS_AGY_EXE;
  const la = process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local');
  return path.join(la, 'agy', 'bin', 'agy.exe');
}

/**
 * The environment that makes agy use ONE account's home folder and nothing else.
 * SSH_CONNECTION makes agy skip the shared OS keyring, so the PC's own agy login
 * is never read or overwritten (measured 2026-11-23). CLOUD_CODE_URL is removed so
 * this maintenance run talks to Google directly — it must not loop back into us.
 */
export function isolatedEnv(home, base = process.env) {
  const env = { ...base };
  for (const k of Object.keys(env)) if (/^cloud_code_url$/i.test(k)) delete env[k];
  const gem = path.join(home, '.gemini');
  Object.assign(env, {
    USERPROFILE: home,
    HOME: home,
    GEMINI_CLI_HOME: gem,
    ANTIGRAVITY_GEMINI_DIR: gem,
    ANTIGRAVITY_APP_DATA_DIR: path.join(gem, 'antigravity-cli'),
    SSH_CONNECTION: '127.0.0.1 1234 127.0.0.1 22',
    AGY_CLI_DISABLE_AUTO_UPDATE: 'true',
  });
  return env;
}

function runAgy(exe, args, { env, cwd, timeoutMs }) {
  return new Promise((resolve) => {
    let out = '', err = '', done = false, p;
    const fin = (r) => { if (!done) { done = true; clearTimeout(timer); resolve(r); } };
    const timer = setTimeout(() => { try { p?.kill(); } catch { /* gone */ } fin({ code: null, out, err, error: 'timeout' }); }, timeoutMs);
    try { p = spawn(exe, args, { env, cwd, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }); }
    catch (e) { fin({ code: null, out, err, error: `spawn failed: ${e.message}` }); return; }
    p.stdout.on('data', d => { out += d; });
    p.stderr.on('data', d => { err += d; });
    p.on('error', e => fin({ code: null, out, err, error: e.message }));
    p.on('close', code => fin({ code, out, err, error: null }));
  });
}

/**
 * Get a fresh token for one account by letting agy refresh it, then reading the
 * file again. Same { accessToken, refreshToken, expiresAt } shape as the other
 * providers' refresh functions, so ensureTokenFresh stays provider-agnostic.
 * A "please sign in" answer is a SOFT failure (`err.soft`) — agy's guess, to be checked
 * again before anyone is told to log in; anything else that fails is transient. A missing
 * home folder is the only hard 401 left here (a broken config entry, not a login state).
 */
export async function refreshGoogleToken(home, { agyExe = defaultAgyExe(), timeoutMs = 60_000, run = runAgy } = {}) {
  if (!home) { const e = new Error('google account has no home folder'); e.status = 401; throw e; }
  const before = readGoogleToken(home);
  const cwd = path.join(os.tmpdir(), 'iris-gate-google-run');
  try { mkdirSync(cwd, { recursive: true }); } catch { /* best effort */ }
  const r = await run(agyExe, ['models'], { env: isolatedEnv(home), cwd, timeoutMs });
  const text = `${r.out}\n${r.err}`;
  const after = readGoogleToken(home);
  // local patch 2026-11-25 IRIS: agy's WORDS are not Google's verdict. All five "not signed in" answers this PC
  // ever got (11-23..11-25) came within 3 s of leaving standby, and the same command a few minutes later renewed
  // the token with no new login. So this is a SOFT failure (`err.soft`, no status): the account manager takes the
  // account out of rotation, checks again on a schedule and only calls it "needs re-login" after repeated
  // failures. A token file that cannot be read right after the run (agy replaces it) is the same kind of guess.
  const saysSignIn = /sign in|not logged in|log ?in to/i.test(text) && r.code !== 0;
  if (saysSignIn || !after) {
    // The file may hold a token minted during (or just before) this very run — hand it back; the caller checks
    // it against Google before trusting the account again.
    const fresh = after && after.expiresAt && after.expiresAt > Date.now() + 60_000
      && (!before || after.accessToken !== before.accessToken);
    if (fresh) return after;
    const e = new Error(saysSignIn
      ? 'agy says this account is not signed in — log in again in its folder'
      : 'token file missing after agy run');
    e.soft = true;
    throw e;
  }
  if (r.error || r.code !== 0) {
    // agy failed, but if the file still holds a token that is not expired, use it.
    if (after.expiresAt && after.expiresAt > Date.now() + 60_000) return after;
    throw new Error(`agy refresh run failed (${r.error || `exit ${r.code}`})`);
  }
  if (before && after.accessToken === before.accessToken) {
    // agy renews only right before expiry (Go oauth2 style), so an early run can leave the file as it was.
    // A still-valid token is not a failure: hand it back marked `unchanged`, and the caller waits for the
    // real expiry before running agy again (no agy launch per request in the last minutes).
    if (after.expiresAt && after.expiresAt > Date.now() + 15_000) return { ...after, unchanged: true };
    throw new Error('agy ran but did not renew the token file');
  }
  return after;
}

async function postJson(token, method, body, { signal, upstream = GOOGLE_UPSTREAM, fetchFn = fetch } = {}) {
  const res = await fetchFn(`${upstream}/v1internal:${method}`, {
    method: 'POST',
    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json', 'user-agent': googleUA() },
    body: JSON.stringify(body),
    signal,
  });
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch { /* not json */ }
  return { status: res.status, json, text };
}

/** The account's Google project and tier (zero-spend; agy asks the same at start). */
export async function fetchGoogleProject(token, opts = {}) {
  let r;
  try { r = await postJson(token, 'loadCodeAssist', { metadata: { ideType: 'ANTIGRAVITY' } }, opts); }
  catch (e) { return { error: e?.name === 'AbortError' || e?.name === 'TimeoutError' ? 'timeout' : (e?.message || String(e)) }; }
  // The body is kept (capped) so a suspension signal on this background read halts Google too (Codex review C-2).
  if (r.status !== 200) return { status: r.status, error: `loadCodeAssist ${r.status}`, text: String(r.text || '').slice(0, 8192) };
  return {
    status: 200,
    project: typeof r.json?.cloudaicompanionProject === 'string' ? r.json.cloudaicompanionProject : null,
    tier: r.json?.currentTier?.id || null,
  };
}

/**
 * Map Google's quota summary onto the fields the rest of the proxy already reads
 * (same normalisation as Codex): the Gemini group's weekly bucket → sevenDay, a
 * shorter bucket (paid plans have a 5-hour one) → fiveHour. Utilization = 1 − remaining.
 * Pure — the tests call it directly.
 */
export function parseGoogleQuota(json) {
  const groups = Array.isArray(json?.groups) ? json.groups : null;
  if (!groups) return { error: 'no quota groups' };
  const all = [];
  for (const g of groups) {
    for (const b of (Array.isArray(g?.buckets) ? g.buckets : [])) {
      const rem = typeof b?.remainingFraction === 'number' ? b.remainingFraction
        : typeof b?.remaining_fraction === 'number' ? b.remaining_fraction : null;
      const reset = Date.parse(b?.resetTime || b?.reset_time || '');
      all.push({
        group: String(g?.displayName || g?.name || ''),
        id: String(b?.id || ''),
        window: String(b?.window || ''),
        remaining: rem == null ? null : Math.max(0, Math.min(1, rem)),
        resetAt: Number.isFinite(reset) ? reset : null,
      });
    }
  }
  // Only the Gemini group counts for routing: the IRIS window never offers the
  // Claude/GPT models agy also lists (2026-11-23 user decision).
  const gem = all.filter(b => /gemini/i.test(b.group) || /^gemini/i.test(b.id));
  const pick = (re) => gem.find(b => b.remaining != null && re.test(b.window));
  const week = pick(/week/i);
  const short = gem.find(b => b.remaining != null && !/week/i.test(b.window));
  const toBucket = b => (b ? { utilization: 1 - b.remaining, resetAt: b.resetAt } : null);
  return {
    sevenDay: toBucket(week),
    fiveHour: toBucket(short),
    googleBuckets: all,
  };
}

/** One background quota read for an account (zero-spend). */
export async function fetchGoogleUsage(token, project, opts = {}) {
  if (!project) return { error: 'project unknown' };
  try {
    const r = await postJson(token, 'retrieveUserQuotaSummary', { project }, opts);
    if (r.status === 401) return { status: 401, error: 'token rejected' };
    if (r.status !== 200) return { status: r.status, error: `quota ${r.status}`, text: String(r.text || '').slice(0, 8192) };
    return parseGoogleQuota(r.json);
  } catch (e) {
    return { error: e?.name === 'AbortError' ? 'probe timed out' : (e?.message || String(e)) };
  }
}

/**
 * Find the byte ranges of every TOP-LEVEL `"project": "<string>"` value in a JSON
 * object body, by walking the structure (strings with escapes, nested objects and
 * arrays) without parsing numbers — so nothing else in the body is reinterpreted.
 * Returns [] for anything that is not a well-formed top-level object.
 * Each range = { start, end } of the value's characters inside the quotes.
 */
export function topLevelProjectRanges(buf) {
  const n = buf.length;
  let i = 0;
  const ws = () => { while (i < n && (buf[i] === 0x20 || buf[i] === 0x0a || buf[i] === 0x0d || buf[i] === 0x09)) i++; };
  // Returns [start, end) of a string's inner bytes, with i past the closing quote; null if malformed.
  const str = () => {
    if (buf[i] !== 0x22) return null;
    const start = ++i;
    while (i < n) {
      const c = buf[i];
      if (c === 0x5c) { i += 2; continue; }       // backslash escape
      if (c === 0x22) { const end = i; i++; return [start, end]; }
      if (c < 0x20) return null;                   // raw control char = not JSON
      i++;
    }
    return null;
  };
  // Skips one value of any kind; false if malformed.
  const skip = () => {
    ws();
    const c = buf[i];
    if (c === 0x22) return str() != null;
    if (c === 0x7b || c === 0x5b) {
      const stack = [c === 0x7b ? 0x7d : 0x5d];
      i++;
      while (i < n && stack.length) {
        const d = buf[i];
        if (d === 0x22) { if (str() == null) return false; continue; }
        if (d === 0x7b) stack.push(0x7d); else if (d === 0x5b) stack.push(0x5d);
        else if (d === 0x7d || d === 0x5d) { if (stack.pop() !== d) return false; }
        i++;
      }
      return stack.length === 0;
    }
    const start = i;
    while (i < n && !(buf[i] === 0x2c || buf[i] === 0x7d || buf[i] === 0x5d || buf[i] === 0x20 || buf[i] === 0x0a || buf[i] === 0x0d || buf[i] === 0x09)) i++;
    return i > start;
  };
  const ranges = [];
  ws();
  if (buf[i] !== 0x7b) return [];
  i++;
  ws();
  if (buf[i] === 0x7d) return [];
  for (;;) {
    ws();
    const key = str();
    if (!key) return [];
    ws();
    if (buf[i] !== 0x3a) return [];
    i++;
    ws();
    // A key may be written with escapes ("project" is "project" too — Codex review D-1): decode those by JSON rules.
    let isProject = key[1] - key[0] === 7 && buf.toString('latin1', key[0], key[1]) === 'project';
    if (!isProject && buf.indexOf(0x5c, key[0]) !== -1 && buf.indexOf(0x5c, key[0]) < key[1]) {
      try { isProject = JSON.parse(buf.toString('utf8', key[0] - 1, key[1] + 1)) === 'project'; } catch { return []; }
    }
    if (isProject && buf[i] === 0x22) {
      const v = str();
      if (!v) return [];
      ranges.push({ start: v[0], end: v[1] });
    } else if (!skip()) return [];
    ws();
    if (buf[i] === 0x2c) { i++; continue; }
    if (buf[i] === 0x7d) break;
    return [];
  }
  i++;
  ws();
  return i === n ? ranges : [];
}

/**
 * Swap every top-level `"project"` string value of a request body for the
 * account's own project (design ㉰-③). Byte-level: only those value bytes change.
 * Returns the same Buffer when there is nothing to change (empty, compressed,
 * not a well-formed JSON object, no top-level project, already equal).
 * A project id with characters that would need JSON escaping is refused (unchanged).
 */
export function rewriteGoogleProject(body, project, contentEncoding = '') {
  if (!project || !Buffer.isBuffer(body) || body.length === 0) return body;
  if (contentEncoding && !/^identity$/i.test(contentEncoding)) return body;
  if (!/^[A-Za-z0-9._:-]{1,200}$/.test(project)) return body;
  const ranges = topLevelProjectRanges(body);
  if (!ranges.length) return body;
  const want = Buffer.from(project, 'latin1');
  if (ranges.every(r => body.subarray(r.start, r.end).equals(want))) return body;
  const parts = [];
  let at = 0;
  for (const r of ranges) {
    parts.push(body.subarray(at, r.start), want);
    at = r.end;
  }
  parts.push(body.subarray(at));
  return Buffer.concat(parts);
}

/**
 * Whether an upstream error body is Google telling us the account is suspended
 * or in breach of terms. On this signal NO other account may be tried — rotating
 * would hand every remaining account to the same check (design ㉱-④).
 */
export function isGoogleSuspension(text) {
  return /TOS_VIOLATION|terms of service|account (has been |is )?(suspended|disabled|banned)|suspended/i.test(String(text || ''));
}

