// local patch 2026-11-25 IRIS: do not renew login tokens in the first moments after the PC wakes up.
//
// Why: every "needs re-login" a Google account got on this PC (5 of 5, 11-23..11-25) landed within three seconds
// of Windows leaving standby — the overdue refresh ran before the network was back and its failure was read as a
// rejected login. For Anthropic / OpenAI the same moment is worse: their token endpoint rotates the refresh token
// on every grant, so a request that reaches the server while the reply is lost leaves us holding a dead token.
//
// What: a clock that jumps (the timer that should fire every 10 s fired much later) means the process was
// suspended. From then on token refreshes wait until one of the login hosts answers, 30 s at most, and the
// refreshes that were waiting start a little apart instead of all at once. Requests whose token is still valid
// never wait here — only a refresh that is about to be SENT does.
//
// This also holds the two small helpers the soft-failure rechecks use (isOnline, isAuthServerRefusal), so the
// "is the network there" question has one answer everywhere.
import { proxyFetch } from './upstream-fetch.js';

const PROBE_URL = {
  anthropic: 'https://platform.claude.com/',
  codex: 'https://auth.openai.com/',
  google: 'https://daily-cloudcode-pa.googleapis.com/',
};

/**
 * Can this PC reach the provider's login host right now? Any HTTP answer counts (even 403/404): the question is
 * "is there a network path", not "is the login good". No credential is sent. Resolving a name is NOT enough —
 * a cached DNS answer or a captive portal passes that while HTTPS still fails (Codex design review 2026-11-25).
 */
export async function isOnline(provider = 'anthropic', { fetchFn = proxyFetch, timeoutMs = 4_000 } = {}) {
  const url = PROBE_URL[provider] || PROBE_URL.anthropic;
  try {
    const res = await fetchFn(url, { method: 'HEAD', redirect: 'manual', signal: AbortSignal.timeout(timeoutMs) });
    try { await res.body?.cancel(); } catch { /* nothing to drain */ }
    return true;
  } catch {
    return false;
  }
}

/** True when ANY of the login hosts answers. */
export async function isAnyOnline(opts = {}) {
  const tries = Object.keys(PROBE_URL).map(p => isOnline(p, opts));
  return (await Promise.all(tries)).some(Boolean);
}

/**
 * Is this 400/401/403 body the login server's own refusal? OAuth servers answer a bad grant with a JSON object
 * carrying an error (`{"error":"invalid_grant",...}` or `{"error":{"type"|"code"|"message":...}}`). A security
 * appliance, a captive portal or a proxy answers the same status with HTML, an empty body or some other shape —
 * that says nothing about the refresh token and must not sideline the account for good.
 */
export function isAuthServerRefusal(text) {
  let j;
  try { j = JSON.parse(String(text || '')); } catch { return false; }
  if (!j || typeof j !== 'object' || Array.isArray(j)) return false;
  const e = j.error;
  // Only the codes a login server uses to say "this grant is dead" - not any JSON with an error in it (an
  // appliance can answer {"error":{"message":"Blocked by policy"}} just as well; Codex code review 2026-11-25).
  // An unknown shape is rechecked on the soft schedule instead: a few extra tries, never a wrongly dead account.
  if (typeof e === 'string') return REFUSAL_CODES.has(e.trim().toLowerCase());
  if (e && typeof e === 'object') return [e.code, e.type].some(v => typeof v === 'string' && REFUSAL_CODES.has(v.trim().toLowerCase()));
  return false;
}

const REFUSAL_CODES = new Set([
  'invalid_grant', 'invalid_client', 'unauthorized_client', 'access_denied', // OAuth 2.0 (RFC 6749 5.2) - Anthropic, OpenAI
  'refresh_token_reused', 'refresh_token_expired', 'refresh_token_invalidated', // OpenAI (codex-rs login/auth/manager.rs)
  'invalid_refresh_token', 'token_revoked',
]);

const realSleep = (ms) => new Promise(resolve => { const t = setTimeout(resolve, ms); t.unref?.(); });

/**
 * @param opts.tickMs    how often the clock is looked at
 * @param opts.jumpMs    a tick this much later than expected = the process was suspended
 * @param opts.holdMs    longest wait for the network after waking
 * @param opts.windowMs  for this long after waking, refreshes start `gapMs` apart
 */
export function createWakeGuard({
  now = () => Date.now(), sleep = realSleep, online = isAnyOnline, log = (m) => console.log(m),
  tickMs = 10_000, jumpMs = 45_000, holdMs = 30_000, windowMs = 120_000, gapMs = 1_500, maxGapMs = 9_000, probeMs = 2_000, pollMs = 250,
} = {}) {
  let lastTick = now();
  let wokeAt = 0;      // when the last wake was noticed (0 = never)
  let holdUntil = 0;   // refreshes wait until this time (0 = not holding)
  let slot = 0;        // order of arrival inside the stagger window
  let timer = null;
  let probing = null;

  async function probeLoop() {
    while (now() < holdUntil) {
      let up = false;
      try { up = await online(); } catch { up = false; }
      if (up) { holdUntil = 0; break; }
      await sleep(probeMs);
    }
    probing = null;
  }

  function arm(t, gap) {
    wokeAt = t; holdUntil = t + holdMs; slot = 0;
    log(`[TeamClaude] WAKE: the clock jumped ${Math.round(gap / 1000)}s — token refreshes wait for the network (up to ${Math.round(holdMs / 1000)}s)`);
    if (!probing) probing = probeLoop();
  }

  /** Look at the clock. Called by the timer AND by wait(), so a refresh that runs before the timer still notices. */
  function tick() {
    const t = now();
    const gap = t - lastTick;
    lastTick = t;
    if (gap > tickMs + jumpMs) arm(t, gap);
    return gap;
  }

  return {
    tick,
    /** Resolves when a token refresh may be sent. Immediate unless the PC just woke up. */
    async wait() {
      tick();
      const t = now();
      const inWindow = wokeAt && t - wokeAt < windowMs;
      if (!inWindow && t >= holdUntil) return { waitedMs: 0 };
      const mine = slot++;
      while (now() < holdUntil) await sleep(pollMs);
      const gap = Math.min(mine * gapMs, maxGapMs);
      if (gap > 0) await sleep(gap);
      return { waitedMs: now() - t };
    },
    state: () => ({ wokeAt, holding: now() < holdUntil }),
    start() { if (!timer) { timer = setInterval(tick, tickMs); timer.unref?.(); } return this; },
    stop() { if (timer) clearInterval(timer); timer = null; holdUntil = 0; },
  };
}

