// local patch 2026-11-25 IRIS: soft login failures ("checking" before "needs re-login"), recovery in one piece,
// the wake guard, and the manual recheck. No real account, no network, no agy: every outside call is a fake.
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, mkdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { AccountManager } from './src/account-manager.js';
import { AuthHealth } from './src/auth-health.js';
import { Prober } from './src/prober.js';
import { refreshGoogleToken, parseGoogleQuota } from './src/google-auth.js';
import { createWakeGuard, isAuthServerRefusal } from './src/wake-guard.js';
import { syncAccountsFromDisk } from './src/sync-accounts.js';

const MIN = 60_000;
const tokenFile = (token, expiresAt) => JSON.stringify({
  token: { access_token: token, token_type: 'Bearer', refresh_token: 'R-GOOGLE', expiry: new Date(expiresAt).toISOString(), expires_in: 3599 },
  auth_method: 'consumer', id_token_email: 'g@example.test',
});
async function writeToken(home, token, expiresAt = Date.now() + 3600_000) {
  const d = join(home, '.gemini', 'antigravity-cli');
  await mkdir(d, { recursive: true });
  await writeFile(join(d, 'antigravity-oauth-token'), tokenFile(token, expiresAt));
}
const softError = () => { const e = new Error('agy says this account is not signed in — log in again in its folder'); e.soft = true; return e; };

/** One Google account whose token expired while the PC slept, plus the health layer with a counted notifier. */
async function rig({ refresh, verify = async () => ({ status: 200, project: 'p-1', tier: 'free' }), online = async () => true } = {}) {
  const dir = await mkdtemp(join(tmpdir(), 'tc-soft-'));
  const home = join(dir, 'g1');
  await writeToken(home, 'OLD', Date.now() - 60_000);
  const calls = { google: 0, anthropic: 0, codex: 0 };
  const am = new AccountManager([
    { name: 'a1', type: 'oauth', provider: 'anthropic', accessToken: 'A', refreshToken: 'RA', expiresAt: Date.now() + 86400000 },
    { name: 'google-1', type: 'oauth', provider: 'google', importFrom: home },
  ], 0.99, {
    googleHaltFile: join(dir, 'halt.json'),
    refreshFn: async () => { calls.anthropic++; throw new Error('must not be called'); },
    codexRefreshFn: async () => { calls.codex++; throw new Error('must not be called'); },
    googleRefreshFn: async (h) => { calls.google++; return refresh(h, calls.google); },
  });
  am._onlineFn = online;
  am._googleVerifyFn = verify;
  const alerts = [];
  const health = new AuthHealth(am, { configPath: join(dir, 'teamclaude.json'), notify: (t, b) => { alerts.push([t, b]); return true; } });
  am._authHealth = health;
  const g = am.accounts[1];
  return { am, g, home, calls, alerts, health, dir };
}

test('woke from standby: one failed refresh is only "checking" — no dead token, no alert, back by itself a minute later', async () => {
  const fresh = { accessToken: 'NEW', refreshToken: 'R-GOOGLE', expiresAt: Date.now() + 3600_000 };
  const { am, g, calls, alerts, health } = await rig({ refresh: async (h, n) => { if (n === 1) throw softError(); return fresh; } });

  await am.ensureTokenFresh(1);
  assert.equal(calls.google, 1);
  assert.equal(am.authSoftState(g), 'checking');
  assert.equal(g.status, 'active', 'the internal status is not misused for a doubt');
  assert.equal(g._deadRefreshToken ?? null, null, 'no dead-token mark for a guess');
  assert.equal(am.unavailableReason(g), 'checking', 'out of rotation while it is being checked');
  assert.equal(am.getActiveAccount(null, 'gemini-4-hydrogen-low', null, null, 'google'), null);
  const st = am.getStatus().accounts.find(a => a.name === 'google-1');
  assert.equal(st.status, 'error', 'readers that only know `status` must not take it for usable');
  assert.equal(st.auth.state, 'checking');
  assert.equal(st.auth.check.fails, 1);
  assert.equal(health.stateOf(g), 'checking');
  assert.equal(alerts.length, 0);
  assert.equal(g._authSoft.nextAt - g._authSoft.lastAt, 1 * MIN, 'first recheck one minute later');

  // requests, the prober and a forced refresh do NOT launch agy while the recheck is pending
  await am.ensureTokenFresh(1); await am.ensureTokenFresh(1, true); await am.ensureTokenFresh(1, true);
  assert.equal(calls.google, 1);
  await am.recheckDue(g._authSoft.nextAt - 1);
  assert.equal(calls.google, 1, 'not before its time');

  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(calls.google, 2);
  assert.equal(g._authSoft, null);
  assert.equal(g.credential, 'NEW');
  assert.equal(am.unavailableReason(g), null);
  assert.equal(health.stateOf(g), 'ok');
  assert.equal(alerts.length, 0, 'nobody was told anything');
  assert.equal(am.getActiveAccount(null, 'gemini-4-hydrogen-low', null, null, 'google').name, 'google-1');
});

test('timetable: rechecks 1, 5 and 15 minutes after the first failure; needs-login + ONE alert only after all three fail; then every 2 h, and it can still come back', async () => {
  let ok = false;
  const { am, g, calls, alerts, health } = await rig({ refresh: async () => { if (!ok) throw softError(); return { accessToken: 'NEW', refreshToken: 'R-GOOGLE', expiresAt: Date.now() + 3600_000 }; } });
  await am.ensureTokenFresh(1);
  const gaps = [g._authSoft.nextAt - g._authSoft.lastAt];
  for (let i = 0; i < 2; i++) {
    await am.recheckDue(g._authSoft.nextAt);
    assert.equal(am.authSoftState(g), 'checking', `still checking after recheck ${i + 1}`);
    assert.equal(alerts.length, 0);
    gaps.push(g._authSoft.nextAt - g._authSoft.lastAt);
  }
  assert.deepEqual(gaps, [1 * MIN, 5 * MIN, 15 * MIN]);
  await am.recheckDue(g._authSoft.nextAt); // the third recheck fails too
  assert.equal(calls.google, 4);
  assert.equal(am.authSoftState(g), 'needs-login');
  assert.equal(am.unavailableReason(g), 'error');
  assert.equal(health.stateOf(g), 'needs-login');
  assert.equal(alerts.length, 1);
  assert.match(alerts[0][0], /재로그인 필요/);
  assert.match(alerts[0][1], /다시 확인/);
  assert.doesNotMatch(alerts[0][1], /다른 PC/, 'the "logged in elsewhere" sentence is not for a guess');
  assert.equal(g._authSoft.nextAt - g._authSoft.lastAt, 120 * MIN, 'slow rechecks continue');
  assert.equal(g._deadRefreshToken ?? null, null);

  ok = true;
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(g._authSoft, null);
  assert.equal(health.stateOf(g), 'ok');
  assert.equal(alerts.length, 2);
  assert.match(alerts[1][0], /다시 정상/);
});

test('a recheck that cannot reach the provider is not counted; agy handing back a token is not proof until Google answers', async () => {
  let up = false;
  let verdict = { error: 'fetch failed' };
  const { am, g, calls, alerts } = await rig({
    refresh: async (h, n) => { if (n === 1) throw softError(); return { accessToken: 'NEW', refreshToken: 'R-GOOGLE', expiresAt: Date.now() + 3600_000 }; },
    online: async () => up,
    verify: async () => verdict,
  });
  await am.ensureTokenFresh(1);
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(calls.google, 1, 'offline: agy is not even started');
  assert.equal(g._authSoft.fails, 1);
  assert.equal(g._authSoft.nextAt - g._authSoft.offlineAt, 1 * MIN);
  assert.equal(g._authSoft.uncounted, 1);

  up = true; // online, agy returns a token, but the check against Google cannot be made
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(calls.google, 2);
  assert.equal(am.authSoftState(g), 'checking', 'still out of rotation');
  assert.equal(g._authSoft.fails, 1);

  verdict = { status: 401, error: 'loadCodeAssist 401' }; // Google refuses the token: that IS a failed check
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(g._authSoft.fails, 2);

  verdict = { status: 200, project: 'p-9', tier: 'free' };
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(g._authSoft, null);
  assert.equal(g.googleProject, 'p-9');
  assert.equal(alerts.length, 0);
});

test('11-25 19:34 relapse: a token renewed outside (file adopted) + a good quota read brings the account back and it STAYS back', async () => {
  const { am, g, home, calls } = await rig({ refresh: async () => { throw softError(); } });
  await am.ensureTokenFresh(1);
  assert.equal(am.authSoftState(g), 'checking');
  await writeToken(home, 'RENEWED', Date.now() + 3600_000); // someone ran agy in that folder
  const prober = new Prober(am, {
    intervalMs: 0,
    googleProjectFn: async () => ({ status: 200, project: 'p-1', tier: 'free' }),
    googleProbeFn: async (token) => { assert.equal(token, 'RENEWED'); return parseGoogleQuota({ groups: [{ displayName: 'Gemini Models', buckets: [{ id: 'gemini-weekly', window: 'weekly', remainingFraction: 0.9, resetTime: new Date(Date.now() + 86400000).toISOString() }] }] }); },
  });
  await prober.probeAccount(g);
  assert.equal(g.credential, 'RENEWED');
  assert.equal(g._authSoft, null, 'Google answered with this token → confirmed');
  assert.equal(am.unavailableReason(g), null);
  for (let i = 0; i < 3; i++) await am.ensureTokenFresh(1); // the next calls used to flip it back to error
  await prober.probeAccount(g);
  assert.equal(g.status, 'active');
  assert.equal(am.unavailableReason(g), null);
  assert.equal(g._deadRefreshToken ?? null, null);
  assert.equal(calls.google, 1, 'no extra agy run was needed');
});

test('a Google halt stops rechecks; a re-login into a new folder ends the recheck of the old one', async () => {
  const { am, g, calls, dir } = await rig({ refresh: async () => { throw softError(); } });
  await am.ensureTokenFresh(1);
  am.haltGoogle('TOS_VIOLATION', 'google-1');
  await am.recheckDue(g._authSoft.nextAt);
  assert.equal(calls.google, 1);
  am.clearGoogleHalt();

  const home2 = join(dir, 'g2');
  await writeToken(home2, 'RELOGIN', Date.now() + 3600_000);
  const disk = { accounts: [{ name: 'a1', type: 'oauth', provider: 'anthropic', accessToken: 'A', refreshToken: 'RA', expiresAt: Date.now() + 86400000 }, { name: 'google-1', type: 'oauth', provider: 'google', importFrom: home2 }] };
  const mem = { accounts: JSON.parse(JSON.stringify(disk.accounts)) };
  mem.accounts[1].importFrom = g.home;
  await syncAccountsFromDisk(disk, mem, am);
  assert.equal(g.home, home2);
  assert.equal(g._authSoft, null);
  assert.equal(g.credential, 'RELOGIN');
  assert.equal(am.unavailableReason(g), null);
});

test('Anthropic: a 403 that is not the login server\'s refusal is only "checking"; a real refusal on recheck is the old hard path; a late failure never kills a new login', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'tc-soft-a-'));
  let mode = 'html';
  let release;
  const refreshFn = async (rt) => {
    if (mode === 'html') { const e = new Error('Token refresh failed (403): <html>blocked</html>'); e.unexpectedReply = true; e.httpStatus = 403; throw e; }
    if (mode === 'refuse') { const e = new Error('Token refresh failed (400): {"error":"invalid_grant"}'); e.status = 400; throw e; }
    if (mode === 'slow-refuse') { await new Promise(r => { release = r; }); const e = new Error('Token refresh failed (400): {"error":"invalid_grant"}'); e.status = 400; throw e; }
    return { accessToken: `A-${rt}`, refreshToken: `${rt}+`, expiresAt: Date.now() + 3600_000 };
  };
  const am = new AccountManager([{ name: 'c1', type: 'oauth', provider: 'anthropic', accessToken: 'A', refreshToken: 'RT1', expiresAt: Date.now() - 1000 }], 0.99, { googleHaltFile: join(dir, 'h.json'), refreshFn });
  am._onlineFn = async () => true;
  const a = am.accounts[0];
  await am.ensureTokenFresh(0);
  assert.equal(am.authSoftState(a), 'checking');
  assert.equal(a._deadRefreshToken ?? null, null);
  assert.equal(a.status, 'active');

  mode = 'refuse';
  await am.recheckDue(a._authSoft.nextAt);
  assert.equal(a._authSoft, null);
  assert.equal(a.status, 'error');
  assert.equal(a._deadRefreshToken, 'RT1', 'a real refusal: never sent again');
  mode = 'ok';
  await am.ensureTokenFresh(0); await am.ensureTokenFresh(0, true);
  assert.equal(a.status, 'error', 'the dead-token guard still holds');

  // late failure: a refresh with RT2 is in flight, a re-login brings RT3, then the old one is refused
  am.updateAccountTokens(0, { accessToken: 'A2', refreshToken: 'RT2', expiresAt: Date.now() - 1000 });
  assert.equal(a.status, 'active');
  mode = 'slow-refuse';
  const inFlight = am.ensureTokenFresh(0);
  await new Promise(r => setTimeout(r, 20));
  am.updateAccountTokens(0, { accessToken: 'A3', refreshToken: 'RT3', expiresAt: Date.now() + 3600_000 });
  release();
  await inFlight;
  assert.equal(a.status, 'active');
  assert.equal(a.refreshToken, 'RT3');
  assert.notEqual(a._deadRefreshToken, 'RT3');
});

test('manual recheck: one run however often it is asked; never re-sends a refused token (re-reads the config instead)', async () => {
  let runs = 0;
  let release;
  const { am, g } = await rig({ refresh: async (h, n) => { if (n === 1) throw softError(); runs++; await new Promise(r => { release = r; }); return { accessToken: 'NEW', refreshToken: 'R-GOOGLE', expiresAt: Date.now() + 3600_000 }; } });
