  assert.equal(r1.state, 'ok');
  assert.equal(r2.state, 'ok');
  const r3 = await am.recheckAccount('google-1');
  assert.equal(r3.throttled, true, 'a second click within 20 s does not run again');
  assert.equal((await am.recheckAccount('nobody')).ok, false);
  assert.equal(g._authSoft, null);

  // a refresh token the login server refused: reload is asked, the refresh function is not
  const a = am.accounts[0];
  a.status = 'error'; a._deadRefreshToken = a.refreshToken;
  let reloads = 0;
  const r4 = await am.recheckAccount('a1', { reload: async () => { reloads++; } });
  assert.equal(reloads, 1);
  assert.equal(r4.state, 'needs-login');
});

test('refreshGoogleToken: "sign in" + failed exit is a SOFT failure (no status); a token minted during the run is handed back; a missing folder stays a hard 401', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'tc-soft-g-'));
  await writeToken(dir, 'OLD', Date.now() - 60_000);
  const signIn = async () => ({ code: 1, out: '', err: 'Please sign in to continue', error: null });
  await assert.rejects(() => refreshGoogleToken(dir, { agyExe: 'x', run: signIn }), (e) => e.soft === true && e.status === undefined);
  const renews = async () => { await writeToken(dir, 'MINTED', Date.now() + 3600_000); return { code: 1, out: '', err: 'Please sign in to continue', error: null }; };
  assert.equal((await refreshGoogleToken(dir, { agyExe: 'x', run: renews })).accessToken, 'MINTED');
  await assert.rejects(() => refreshGoogleToken(null, { agyExe: 'x', run: signIn }), (e) => e.status === 401 && e.soft !== true);
  const empty = await mkdtemp(join(tmpdir(), 'tc-soft-e-'));
  await assert.rejects(() => refreshGoogleToken(empty, { agyExe: 'x', run: async () => ({ code: 0, out: 'ok', err: '', error: null }) }), (e) => e.soft === true);
});

test('isAuthServerRefusal: only the login server\'s own JSON refusal counts', () => {
  assert.equal(isAuthServerRefusal('{"error":"invalid_grant","error_description":"Refresh token not found or invalid"}'), true);
  assert.equal(isAuthServerRefusal('{"error":{"message":"Your refresh token has already been used","type":"invalid_request_error","code":"refresh_token_reused"}}'), true);
  assert.equal(isAuthServerRefusal('<html><body>Access blocked by policy</body></html>'), false);
  assert.equal(isAuthServerRefusal(''), false);
