});

test('wake guard: a jumped clock holds refreshes until a login host answers (30 s at most) and lets them go a little apart', async () => {
  let t = 1_000_000;
  let up = false;
  const logs = [];
  const sleeps = [];
  const g = createWakeGuard({ now: () => t, sleep: async (ms) => { sleeps.push(ms); t += ms; }, online: async () => up, log: (m) => logs.push(m) });
  assert.deepEqual(await g.wait(), { waitedMs: 0 }, 'a normal moment: no wait');
  t += 10_000; g.tick();
  assert.equal(g.state().holding, false);

  t += 2 * 3600_000; // two hours of standby
  const first = g.wait(); // runs up to its first await: the jump is noticed and the hold is armed
  assert.equal(g.state().holding, true);
  assert.match(logs[0], /WAKE/);
  up = true;
  const r1 = await first;
  assert.ok(r1.waitedMs > 0 && r1.waitedMs <= 30_000);
  assert.equal(g.state().holding, false);
  const before = t;
  await g.wait(); // the second refresh after the same wake starts a little later
  assert.ok(t - before >= 1_500);

  // never online: the hold still ends
  up = false; t += 10 * 60_000; g.tick();
  const start = t;
  await g.wait();
  assert.ok(t - start >= 30_000 && t - start < 45_000, `held ${t - start} ms`);
  g.stop();
});

test('real server (wake guard switched off so nothing can reach outside): POST /teamclaude/accounts/recheck answers this PC, refuses a web page and bad input', async () => {
  const { spawn } = await import('node:child_process');
  const http = await import('node:http');
  const { once } = await import('node:events');
  const { resolve } = await import('node:path');
  const delay = ms => new Promise(r => setTimeout(r, ms));
  const temp = await mkdtemp(join(tmpdir(), 'tc-soft-srv-'));
  const res0 = http.createServer(); res0.listen(0, '127.0.0.1'); await once(res0, 'listening');
  const port = res0.address().port; await new Promise(r => res0.close(r));
  const base = `http://127.0.0.1:${port}`;
  const config = {
    proxy: { port, apiKey: 'test-proxy-key' }, upstream: 'http://127.0.0.1:9', upstreamProxy: false, quotaProbeSeconds: 0, warmupSeconds: 0, autoUpdate: false, switchThreshold: 0.99,
    accounts: [{ id: 'fx-a', name: 'claude-1', type: 'oauth', provider: 'anthropic', accessToken: 'A-TOKEN', refreshToken: 'RA', expiresAt: Date.now() + 86400000 }],
  };
  const configPath = join(temp, 'teamclaude.json');
  await writeFile(configPath, JSON.stringify(config));
  const child = spawn(process.execPath, ['src/index.js', 'server', '--headless'], {
    cwd: resolve('.'), env: { ...process.env, TEAMCLAUDE_CONFIG: configPath, IRIS_GATE_GOOGLE_HALT_FILE: join(temp, 'halt.json'), TEAMCLAUDE_HOST: '127.0.0.1', TEAMCLAUDE_NOTIFY: '0', TEAMCLAUDE_WAKE_GUARD: '0' }, stdio: ['ignore', 'pipe', 'pipe'],
  });
  let log = ''; child.stdout.on('data', d => { log += d; }); child.stderr.on('data', d => { log += d; });
  try {
    let up = false;
    for (let i = 0; i < 100; i++) { try { const r = await fetch(`${base}/teamclaude/status`); if (r.ok) { up = true; break; } } catch { /* not yet */ } await delay(100); }
    assert.ok(up, `server did not start:\n${log}`);
    const st = await (await fetch(`${base}/teamclaude/status`)).json();
    const a = st.accounts.find(x => x.name === 'claude-1');
    assert.equal(a.status, 'active');
    assert.equal(a.auth.state, 'ok');
    assert.equal(a.auth.check, null);
    const post = (body, headers = {}) => fetch(`${base}/teamclaude/accounts/recheck`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body });
    let r = await post(JSON.stringify({ name: 'claude-1' }));
    assert.equal(r.status, 200);
    const j = await r.json();
    assert.equal(j.ok, true); assert.equal(j.state, 'ok'); assert.equal(j.provider, 'anthropic');
    assert.equal((await post(JSON.stringify({ name: 'claude-1' }), { origin: 'https://evil.example' })).status, 403, 'a web page cannot reach it');
    assert.equal((await post('{}')).status, 400);
    assert.equal((await post('not json')).status, 400);
    assert.equal((await post(JSON.stringify({ name: 'nobody' }))).status, 404);
  } finally {
    child.kill();
  }
});

// ── added after the Codex code review (2026-11-25): nothing is SENT with a login under recheck; late answers change nothing ──
async function miniProxy(accounts, opts = {}) {
  const http = await import('node:http');
  const { createProxyRequestListener } = await import('./src/server.js');
  const hits = [];
  const up = http.createServer((req, res) => { hits.push({ url: req.url, auth: req.headers.authorization }); res.writeHead(200, { 'content-type': 'application/json' }); res.end('{"type":"message"}'); });
  await new Promise(r => up.listen(0, '127.0.0.1', r));
  const am = new AccountManager(accounts, 1, opts);
  am._onlineFn = async () => true;
  const px = http.createServer(createProxyRequestListener({ accountManager: am, upstream: `http://127.0.0.1:${up.address().port}`, config: {} }));
  await new Promise(r => px.listen(0, '127.0.0.1', r));
  const send = (path) => new Promise((resolve, reject) => {
    const req = http.request(`http://127.0.0.1:${px.address().port}${path}`, { method: 'POST', headers: { 'content-type': 'application/json', 'anthropic-version': '2023-06-01' } }, res => { res.resume(); res.on('end', () => resolve(res.statusCode)); });
    req.on('error', reject);
    req.end(JSON.stringify({ model: 'claude-opus-5-5', max_tokens: 1, messages: [{ role: 'user', content: 'x' }] }));
  });
  return { am, hits, send, close: () => { px.close(); up.close(); } };
}

test('nothing is sent with a login under recheck: not on the request that hit the soft failure, not through an explicit pin, not later', async () => {
  const soft = () => { const e = new Error('Token refresh failed (403): blocked page'); e.unexpectedReply = true; e.httpStatus = 403; return e; };
  const { am, hits, send, close } = await miniProxy(
    [{ name: 'only', type: 'oauth', accessToken: 'tok-old', refreshToken: 'r1', expiresAt: Date.now() - 1000 }],
    { refreshFn: async () => { throw soft(); } });
  try {
    const s1 = await send('/v1/messages'); // the refresh fails softly during this very request
    assert.equal(am.authSoftState(am.accounts[0]), 'checking');
    assert.equal(hits.length, 0, 'the request that met the failure was not sent with the doubted token');
    assert.notEqual(s1, 200);
    const s2 = await send('/tc-acct/only/v1/messages'); // an explicit pin to that account
    assert.equal(hits.length, 0, 'a pin does not get through either');
    assert.notEqual(s2, 200);
    await send('/v1/messages');
    assert.equal(hits.length, 0);
    // once it is confirmed, traffic flows again
    am.confirmAuthRecovered(am.accounts[0], 'test');
    am.accounts[0].expiresAt = Date.now() + 3600_000;
    assert.equal(await send('/v1/messages'), 200);
    assert.equal(hits.length, 1);
  } finally { close(); }
});

test('late answers change nothing: an old quota read does not confirm a new doubt; a refresh that returns after a re-login or a removal is dropped', async () => {
  // (a) the quota read started BEFORE the doubt (old token) and answers after it
  let releaseProbe;
  const { am, g } = await rig({ refresh: async () => { throw softError(); } });
  g.expiresAt = Date.now() + 3600_000; // token still good when the read starts
  const prober = new Prober(am, {
    intervalMs: 0,
    googleProjectFn: async () => ({ status: 200, project: 'p-1', tier: 'free' }),
    googleProbeFn: async () => { await new Promise(r => { releaseProbe = r; }); return parseGoogleQuota({ groups: [{ displayName: 'Gemini Models', buckets: [{ id: 'gemini-weekly', window: 'weekly', remainingFraction: 0.9, resetTime: new Date(Date.now() + 86400000).toISOString() }] }] }); },
  });
  const reading = prober.probeAccount(g);
  await new Promise(r => setTimeout(r, 20));
  g.expiresAt = Date.now() - 1000;
  await am.ensureTokenFresh(1); // now the doubt opens
  assert.equal(am.authSoftState(g), 'checking');
  releaseProbe();
  await reading;
  assert.equal(am.authSoftState(g), 'checking', 'an answer to a read that began before the doubt does not clear it');

  // (b) Anthropic: a refresh is in flight, the account is logged in again (a new login generation, even with the
  //     same refresh-token value), then the old refresh SUCCEEDS late
  const dir = await mkdtemp(join(tmpdir(), 'tc-soft-late-'));
  let release;
  const saved = [];
  const am2 = new AccountManager([
    { name: 'x', type: 'oauth', provider: 'anthropic', accessToken: 'A', refreshToken: 'RT', expiresAt: Date.now() - 1000 },
    { name: 'y', type: 'oauth', provider: 'anthropic', accessToken: 'B', refreshToken: 'RY', expiresAt: Date.now() - 1000 },
  ], 0.99, { googleHaltFile: join(dir, 'h.json'), refreshFn: async (rt) => { await new Promise(r => { release = r; }); return { accessToken: `late-${rt}`, refreshToken: `${rt}+`, expiresAt: Date.now() + 3600_000 }; } });
  am2.onTokenRefresh((i, t) => saved.push([i, t.accessToken]));
  const x = am2.accounts[0];
  const p = am2.ensureTokenFresh(0);
  await new Promise(r => setTimeout(r, 20));
  am2.updateAccountTokens(0, { accessToken: 'RELOGIN', refreshToken: 'RT', expiresAt: Date.now() + 3600_000 });
  saved.length = 0;
  release(); await p;
  assert.equal(x.credential, 'RELOGIN', 'the late success did not overwrite the new login');
  assert.deepEqual(saved, []);

  // (c) another account is removed while a refresh is in flight: the result is saved under the account's CURRENT index
  const y = am2.accounts[1];
  const p2 = am2.ensureTokenFresh(1);
  await new Promise(r => setTimeout(r, 20));
  am2.removeAccount(0); // y moves to index 0
  release(); await p2;
  assert.equal(y.credential, 'late-RY', 'y itself still got its own token');
  assert.deepEqual(saved, [[0, 'late-RY']]);
});

test('a PC that stays offline never becomes "needs re-login" by itself; the wait between tries grows to 10 minutes and no check is counted', async () => {
  const { am, g, calls, alerts } = await rig({ refresh: async () => { throw softError(); }, online: async () => false });
  await am.ensureTokenFresh(1);
  const waits = [];
  for (let i = 0; i < 12; i++) { await am.recheckDue(g._authSoft.nextAt); waits.push(Math.round((g._authSoft.nextAt - g._authSoft.offlineAt) / MIN)); }
  assert.equal(calls.google, 1, 'agy was never started while offline');
